{
  "name": "Plameraie BST - Management System",
  "description": "Une application complète de gestion de palmeraie intégrant le suivi de production, la maintenance, les ventes, la finance et des analyses intelligentes propulsées par Gemini.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

export enum UserRole {
  ADMIN = 'ADMIN',
  EMPLOYEE = 'EMPLOYEE'
}

export interface User {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
}

export type ActivityType = 
  | 'CREATION' 
  | 'MAINTENANCE' 
  | 'HARVEST' 
  | 'PRODUCTION' 
  | 'PACKAGING';

export interface Activity {
  id: string;
  type: ActivityType;
  label: string;
  date: string;
  zone: string;
  quantity?: number;
  unit?: string;
  workers: string[];
  cost: number;
  observations?: string;
}

export interface Sale {
  id: string;
  date: string;
  client: string;
  product: string;
  quantity: number;
  unitPrice: number;
  total: number;
}

export interface CashMovement {
  id: string;
  date: string;
  type: 'IN' | 'OUT' | 'WITHDRAWAL';
  amount: number;
  reason: string;
}

export interface AppState {
  users: User[];
  currentUser: User | null;
  activities: Activity[];
  sales: Sale[];
  cashMovements: CashMovement[];
  language: 'FR' | 'EN';
  theme: 'light' | 'dark';
}

import { GoogleGenAI, Modality, Type } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export const getGeminiResponse = async (prompt: string, context?: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  const model = "gemini-3-pro-preview";

  const systemInstruction = `Tu es l'assistant intelligent de Plameraie BST, une application de gestion de palmeraie. 
  Réponds aux questions de l'utilisateur sur la plantation, donne des conseils agronomiques (fertilisation, lutte contre les nuisibles) 
  et aide à l'analyse des données financières si nécessaire. 
  Utilise un ton professionnel et encourageant.
  Context actuel de l'application: ${context || "Aucun context spécifique"}`;

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        systemInstruction,
        thinkingConfig: { thinkingBudget: 32768 }
      }
    });
    return response.text || "Désolé, je n'ai pas pu générer de réponse.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Une erreur est survenue lors de la communication avec l'IA.";
  }
};

export const generateTTS = async (text: string) => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: 'Kore' },
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  } catch (error) {
    console.error("TTS Error:", error);
    return null;
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserRole, AppState, Activity, Sale, CashMovement } from './types';
import { TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Login from './components/Login';
import ActivityModule from './components/ActivityModule';
import SalesModule from './components/SalesModule';
import CashModule from './components/CashModule';
import StatsModule from './components/StatsModule';
import UserManagement from './components/UserManagement';
import ChatBot from './components/ChatBot';

const INITIAL_USERS: User[] = [
  { id: '1', username: 'admin', role: UserRole.ADMIN, password: 'admin' },
  { id: '2', username: 'worker', role: UserRole.EMPLOYEE, password: 'worker' }
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('plameraie_state');
    if (saved) return JSON.parse(saved);
    return {
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      language: 'FR',
      theme: 'light'
    };
  });

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    localStorage.setItem('plameraie_state', JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (state.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state.theme]);

  const t = TRANSLATIONS[state.language];

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
  };

  const toggleLanguage = () => {
    setState(prev => ({ ...prev, language: prev.language === 'FR' ? 'EN' : 'FR' }));
  };

  const toggleTheme = () => {
    setState(prev => ({ ...prev, theme: prev.theme === 'light' ? 'dark' : 'light' }));
  };

  const addActivity = (activity: Omit<Activity, 'id'>) => {
    const newActivity = { ...activity, id: Date.now().toString() };
    setState(prev => ({
      ...prev,
      activities: [newActivity, ...prev.activities],
      cashMovements: activity.cost > 0 ? [
        {
          id: `cm-${Date.now()}`,
          date: activity.date,
          type: 'OUT',
          amount: activity.cost,
          reason: `${activity.label} (${activity.zone})`
        },
        ...prev.cashMovements
      ] : prev.cashMovements
    }));
  };

  const addSale = (sale: Omit<Sale, 'id'>) => {
    const newSale = { ...sale, id: Date.now().toString() };
    setState(prev => ({
      ...prev,
      sales: [newSale, ...prev.sales],
      cashMovements: [
        {
          id: `cm-s-${Date.now()}`,
          date: sale.date,
          type: 'IN',
          amount: sale.total,
          reason: `Vente: ${sale.product} - ${sale.client}`
        },
        ...prev.cashMovements
      ]
    }));
  };

  if (!state.currentUser) {
    return (
      <Login 
        onLogin={handleLogin} 
        users={state.users} 
        t={t} 
        theme={state.theme} 
        language={state.language}
        onLanguageToggle={toggleLanguage}
        onThemeToggle={toggleTheme}
      />
    );
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={state} onAdd={addActivity} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={state} onAdd={addActivity} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={state} onAdd={addActivity} t={t} />;
      case 'production': return <ActivityModule type="PRODUCTION" state={state} onAdd={addActivity} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={state} onAdd={addActivity} t={t} />;
      case 'sales': return <SalesModule state={state} onAdd={addSale} t={t} />;
      case 'cash': 
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <CashModule state={state} t={t} />;
      case 'stats': 
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <StatsModule state={state} t={t} />;
      case 'users':
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <UserManagement state={state} setState={setState} t={t} />;
      default: return <Dashboard state={state} t={t} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        userRole={state.currentUser.role} 
        t={t} 
        onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          t={t} 
          theme={state.theme} 
          language={state.language} 
          onThemeToggle={toggleTheme} 
          onLanguageToggle={toggleLanguage}
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          user={state.currentUser}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>

      <ChatBot state={state} t={t} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  userRole: UserRole;
  t: any;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, userRole, t, onLogout }) => {
  const [isOpen, setIsOpen] = useState(false);

  const menuItems = [
    { id: 'dashboard', label: t.dashboard, icon: '📊', adminOnly: false },
    { id: 'creation', label: t.creation, icon: '🌱', adminOnly: false },
    { id: 'maintenance', label: t.maintenance, icon: '🛠️', adminOnly: false },
    { id: 'harvest', label: t.harvest, icon: '🚜', adminOnly: false },
    { id: 'production', label: t.production, icon: '🏭', adminOnly: false },
    { id: 'packaging', label: t.packaging, icon: '📦', adminOnly: false },
    { id: 'sales', label: t.sales, icon: '💰', adminOnly: false },
    { id: 'cash', label: t.cash, icon: '🏦', adminOnly: true },
    { id: 'stats', label: t.stats, icon: '📈', adminOnly: true },
    { id: 'users', label: t.users, icon: '👥', adminOnly: true },
  ];

  const filteredItems = menuItems.filter(item => !item.adminOnly || userRole === UserRole.ADMIN);

  return (
    <>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-4 left-4 z-50 md:hidden bg-green-700 text-white p-3 rounded-full shadow-lg"
      >
        {isOpen ? '✕' : '☰'}
      </button>

      <aside className={`
        fixed inset-y-0 left-0 z-40 w-64 bg-white dark:bg-slate-800 border-r border-slate-200 dark:border-slate-700
        transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0
        ${isOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-4">
          <div className="flex items-center space-x-2 px-2 py-6 mb-4">
            <div className="w-10 h-10 bg-green-700 rounded-lg flex items-center justify-center text-xl text-white font-bold">P</div>
            <div>
              <h1 className="text-lg font-bold text-slate-800 dark:text-white leading-tight">Plameraie BST</h1>
              <p className="text-xs text-slate-500 dark:text-slate-400">Management System</p>
            </div>
          </div>

          <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {filteredItems.map(item => (
              <button
                key={item.id}
                onClick={() => {
                  setActiveTab(item.id);
                  setIsOpen(false);
                }}
                className={`
                  w-full flex items-center space-x-3 px-3 py-2.5 rounded-lg transition-colors
                  ${activeTab === item.id 
                    ? 'bg-green-50 text-green-700 dark:bg-green-900/30 dark:text-green-400' 
                    : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-slate-700'}
                `}
              >
                <span className="text-lg">{item.icon}</span>
                <span className="text-sm font-medium">{item.label}</span>
              </button>
            ))}
          </nav>

          <div className="pt-4 border-t border-slate-200 dark:border-slate-700 mt-4">
            <button
              onClick={onLogout}
              className="w-full flex items-center space-x-3 px-3 py-2.5 rounded-lg text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
            >
              <span className="text-lg">🚪</span>
              <span className="text-sm font-medium">{t.logout}</span>
            </button>
          </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React from 'react';
import { User } from '../types';

interface HeaderProps {
  t: any;
  theme: 'light' | 'dark';
  language: 'FR' | 'EN';
  onThemeToggle: () => void;
  onLanguageToggle: () => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  user: User;
}

const Header: React.FC<HeaderProps> = ({ 
  t, theme, language, onThemeToggle, onLanguageToggle, searchQuery, setSearchQuery, user 
}) => {
  return (
    <header className="sticky top-0 z-30 flex items-center justify-between bg-white/80 dark:bg-slate-800/80 backdrop-blur-md px-4 md:px-8 py-4 border-b border-slate-200 dark:border-slate-700 transition-colors">
      <div className="flex-1 max-w-md hidden sm:block">
        <div className="relative">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-400">
            🔍
          </span>
          <input
            type="text"
            placeholder={t.searchPlaceholder}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-slate-100 dark:bg-slate-700 border-none rounded-xl focus:ring-2 focus:ring-green-500 text-sm transition-colors dark:text-white"
          />
        </div>
      </div>

      <div className="flex items-center space-x-2 md:space-x-4">
        <button 
          onClick={onLanguageToggle}
          className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 font-medium text-sm transition-colors"
        >
          {language}
        </button>

        <button 
          onClick={onThemeToggle}
          className="p-2 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-700 text-slate-600 dark:text-slate-400 transition-colors"
        >
          {theme === 'light' ? '🌙' : '☀️'}
        </button>

        <div className="h-8 w-px bg-slate-200 dark:bg-slate-700 mx-2"></div>

        <div className="flex items-center space-x-3">
          <div className="hidden md:block text-right">
            <p className="text-sm font-semibold text-slate-800 dark:text-white">{user.username}</p>
            <p className="text-xs text-slate-500 dark:text-slate-400 capitalize">{user.role.toLowerCase()}</p>
          </div>
          <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-900 flex items-center justify-center text-green-700 dark:text-green-300 font-bold border-2 border-white dark:border-slate-700">
            {user.username.charAt(0).toUpperCase()}
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React from 'react';
import { AppState } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, BarChart, Bar } from 'recharts';

interface DashboardProps {
  state: AppState;
  t: any;
}

const Dashboard: React.FC<DashboardProps> = ({ state, t }) => {
  const totalSales = state.sales.reduce((acc, s) => acc + s.total, 0);
  const totalCosts = state.activities.reduce((acc, a) => acc + a.cost, 0);
  const netBalance = totalSales - totalCosts;

  const chartData = state.sales.slice(-7).map(s => ({
    name: s.date.split('-').slice(1).join('/'),
    amount: s.total
  }));

  const stats = [
    { label: t.totalSales, value: `${totalSales.toLocaleString()} FCFA`, color: 'text-green-600', bg: 'bg-green-50 dark:bg-green-900/20', icon: '💰' },
    { label: t.totalCosts, value: `${totalCosts.toLocaleString()} FCFA`, color: 'text-red-600', bg: 'bg-red-50 dark:bg-red-900/20', icon: '📉' },
    { label: t.netBalance, value: `${netBalance.toLocaleString()} FCFA`, color: netBalance >= 0 ? 'text-amber-600' : 'text-red-600', bg: 'bg-amber-50 dark:bg-amber-900/20', icon: '🏦' },
    { label: 'Activités', value: state.activities.length, color: 'text-blue-600', bg: 'bg-blue-50 dark:bg-blue-900/20', icon: '📅' }
  ];

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className={`p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700 ${stat.bg} transition-all hover:shadow-md`}>
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm font-medium text-slate-500 dark:text-slate-400">{stat.label}</p>
                <h3 className={`text-2xl font-bold mt-1 ${stat.color}`}>{stat.value}</h3>
              </div>
              <span className="text-2xl">{stat.icon}</span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-6">Tendance des Ventes (7 dernières)</h3>
          <div className="h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={chartData}>
                <defs>
                  <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#16a34a" stopOpacity={0.1}/>
                    <stop offset="95%" stopColor="#16a34a" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0"/>
                <XAxis dataKey="name" fontSize={12} stroke="#94a3b8" />
                <YAxis fontSize={12} stroke="#94a3b8" />
                <Tooltip />
                <Area type="monotone" dataKey="amount" stroke="#16a34a" fillOpacity={1} fill="url(#colorSales)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-6 rounded-2xl border border-slate-100 dark:border-slate-700 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 dark:text-white mb-4">{t.recentActivities}</h3>
          <div className="space-y-4 max-h-64 overflow-y-auto custom-scrollbar">
            {state.activities.length === 0 ? (
              <p className="text-slate-500 dark:text-slate-400 text-center py-8 italic">Aucune activité enregistrée</p>
            ) : (
              state.activities.slice(0, 5).map(activity => (
                <div key={activity.id} className="flex items-center space-x-4 p-3 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-700 transition-colors">
                  <div className="w-10 h-10 rounded-full bg-green-100 dark:bg-green-900 flex items-center justify-center text-xl">
                    {activity.type === 'CREATION' ? '🌱' : activity.type === 'HARVEST' ? '🚜' : '⚙️'}
                  </div>
                  <div className="flex-1">
                    <p className="text-sm font-semibold text-slate-800 dark:text-white">{activity.label}</p>
                    <p className="text-xs text-slate-500 dark:text-slate-400">{activity.date} - {activity.zone}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold text-slate-700 dark:text-slate-300">-{activity.cost} FCFA</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { AppState } from '../types';

interface CashModuleProps {
  state: AppState;
  t: any;
}

const CashModule: React.FC<CashModuleProps> = ({ state, t }) => {
  const currentBalance = state.cashMovements.reduce((acc, cm) => {
    if (cm.type === 'IN') return acc + cm.amount;
    return acc - cm.amount;
  }, 0);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800 dark:text-white">{t.cash}</h2>
          <p className="text-slate-500 dark:text-slate-400">Journal des flux financiers.</p>
        </div>
        <div className="bg-white dark:bg-slate-800 px-6 py-4 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm text-right">
          <p className="text-xs text-slate-500 dark:text-slate-400 font-bold uppercase tracking-widest">Solde Actuel</p>
          <p className={`text-3xl font-black ${currentBalance >= 0 ? 'text-green-600' : 'text-red-600'}`}>
            {currentBalance.toLocaleString()} FCFA
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-8">
        {state.cashMovements.slice(0, 3).map(cm => (
          <div key={cm.id} className="p-4 bg-white dark:bg-slate-800 rounded-xl border border-slate-100 dark:border-slate-700 shadow-sm">
            <div className="flex justify-between items-start mb-2">
              <span className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${cm.type === 'IN' ? 'bg-green-100 text-green-700 dark:bg-green-900/30' : 'bg-red-100 text-red-700 dark:bg-red-900/30'}`}>
                {cm.type}
              </span>
              <span className="text-xs text-slate-400">{cm.date}</span>
            </div>
            <p className="text-sm font-semibold dark:text-white truncate">{cm.reason}</p>
            <p className={`text-lg font-bold ${cm.type === 'IN' ? 'text-green-600' : 'text-red-600'}`}>
              {cm.type === 'IN' ? '+' : '-'}{cm.amount.toLocaleString()} FCFA
            </p>
          </div>
        ))}
      </div>

      <div className="bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-700/50">
              <tr>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.date}</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.reason}</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.type}</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.amount}</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
              {state.cashMovements.map(cm => (
                <tr key={cm.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30">
                  <td className="px-6 py-4 text-sm dark:text-slate-300">{cm.date}</td>
                  <td className="px-6 py-4 text-sm font-medium dark:text-white">{cm.reason}</td>
                  <td className="px-6 py-4 text-sm capitalize">
                    <span className={cm.type === 'IN' ? 'text-green-600 font-bold' : 'text-red-600 font-bold'}>{t[cm.type.toLowerCase()]}</span>
                  </td>
