import React, { useState, useEffect, useMemo } from 'react';
import { User, UserRole, AppState, Activity, Sale, CashMovement, Notification } from './types';
import { TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Login from './components/Login';
import ActivityModule from './components/ActivityModule';
import SalesModule from './components/SalesModule';
import CashModule from './components/CashModule';
import StatsModule from './components/StatsModule';
import UserManagement from './components/UserManagement';
import ChatBot from './components/ChatBot';
import TutorialModule from './components/TutorialModule';

const INITIAL_USERS: User[] = [
  { id: '1', username: 'admin', role: UserRole.ADMIN, password: 'admin' },
  { id: '2', username: 'worker', role: UserRole.EMPLOYEE, password: 'worker' }
];

const App: React.FC = () => {
  // Helper to get current tab from hash
  const getTabFromHash = () => window.location.hash.replace('#', '') || 'dashboard';

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('plameraie_state');
    if (saved) {
        const parsed = JSON.parse(saved);
        if (!parsed.notifications) parsed.notifications = [];
        return parsed;
    }
    return {
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      notifications: [],
      language: 'FR',
      theme: 'light'
    };
  });

  const [activeTab, setActiveTab] = useState<string>(getTabFromHash());
  const [searchQuery, setSearchQuery] = useState('');

  // Synchronize state with localStorage
  useEffect(() => {
    localStorage.setItem('plameraie_state', JSON.stringify(state));
  }, [state]);

  // Synchronize theme with document class
  useEffect(() => {
    if (state.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state.theme]);

  // Listen for hash changes for routing
  useEffect(() => {
    const handleHashChange = () => {
      setActiveTab(getTabFromHash());
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const t = TRANSLATIONS[state.language];

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
    addNotification('INFO', `${t.login} : ${user.username}`);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    window.location.hash = ''; // Clear hash on logout
  };

  const toggleLanguage = () => {
    setState(prev => ({ ...prev, language: prev.language === 'FR' ? 'EN' : 'FR' }));
  };

  const toggleTheme = () => {
    setState(prev => ({ ...prev, theme: prev.theme === 'light' ? 'dark' : 'light' }));
  };

  const addNotification = (type: Notification['type'], message: string) => {
    const newNotif: Notification = {
      id: Date.now().toString(),
      type,
      message,
      date: new Date().toLocaleString(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  const markAllNotificationsRead = () => {
    setState(prev => ({
      ...prev,
      notifications: prev.notifications.map(n => ({ ...n, isRead: true }))
    }));
  };

  const addActivity = (activity: Omit<Activity, 'id'>) => {
    const newActivity = { ...activity, id: Date.now().toString() };
    const costMessage = activity.cost > 0 ? ` (${activity.cost} FCFA)` : '';

    setState(prev => {
        const updatedCash = activity.cost > 0 ? [
            {
              id: `cm-${Date.now()}`,
              date: activity.date,
              type: 'OUT' as const,
              amount: activity.cost,
              reason: `${activity.label} (${activity.zone})`
            },
            ...prev.cashMovements
          ] : prev.cashMovements;

        const balance = updatedCash.reduce((acc, cm) => cm.type === 'IN' ? acc + cm.amount : acc - cm.amount, 0);
        if (balance < 10000 && balance > 0) {
            addNotification('WARNING', t.lowBalanceAlert);
        }

        return {
            ...prev,
            activities: [newActivity, ...prev.activities],
            cashMovements: updatedCash
        };
    });

    addNotification('SUCCESS', `${t[activity.type.toLowerCase()]} : ${activity.label}${costMessage}`);
  };

  const addSale = (sale: Omit<Sale, 'id'>) => {
    const newSale = { ...sale, id: Date.now().toString() };
    setState(prev => ({
      ...prev,
      sales: [newSale, ...prev.sales],
      cashMovements: [
        {
          id: `cm-s-${Date.now()}`,
          date: sale.date,
          type: 'IN' as const,
          amount: sale.total,
          reason: `Vente: ${sale.product} - ${sale.client}`
        },
        ...prev.cashMovements
      ]
    }));
    addNotification('SUCCESS', `${t.sales} : ${sale.product} à ${sale.client} (${sale.total} FCFA)`);
  };

  const handleTabChange = (tab: string) => {
    window.location.hash = tab;
  };

  if (!state.currentUser) {
    return (
      <Login 
        onLogin={handleLogin} 
        users={state.users} 
        t={t} 
        theme={state.theme} 
        language={state.language}
        onLanguageToggle={toggleLanguage}
        onThemeToggle={toggleTheme}
      />
    );
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={state} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={state} onAdd={addActivity} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={state} onAdd={addActivity} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={state} onAdd={addActivity} t={t} />;
      case 'production': return <ActivityModule type="PRODUCTION" state={state} onAdd={addActivity} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={state} onAdd={addActivity} t={t} />;
      case 'sales': return <SalesModule state={state} onAdd={addSale} t={t} />;
      case 'cash': 
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <CashModule state={state} t={t} />;
      case 'stats': 
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <StatsModule state={state} t={t} />;
      case 'users':
        if (state.currentUser?.role !== UserRole.ADMIN) return <div className="p-8 text-center text-red-500 font-bold">Accès Refusé</div>;
        return <UserManagement state={state} setState={setState} t={t} />;
      case 'tutorial': return <TutorialModule t={t} />;
      default: return <Dashboard state={state} t={t} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={handleTabChange} 
        userRole={state.currentUser.role} 
        t={t} 
        onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col min-w-0">
        <Header 
          t={t} 
          theme={state.theme} 
          language={state.language} 
          onThemeToggle={toggleTheme} 
          onLanguageToggle={toggleLanguage}
          searchQuery={searchQuery}
          setSearchQuery={setSearchQuery}
          user={state.currentUser}
          notifications={state.notifications}
          markAllRead={markAllNotificationsRead}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>

      <ChatBot state={state} t={t} />
    </div>
  );
};

export default App;

