// Simule un appel API vers un serveur distant
const mockApiCall = async (data: any) => {
  return new Promise((resolve) => {
    setTimeout(() => {
      console.log("Données synchronisées avec le serveur central:", data);
      resolve({ success: true });
    }, 1500);
  });
};

export const syncDataWithServer = async (state: AppState, setState: Function) => {
  if (!navigator.onLine) return;

  const unsyncedActivities = state.activities.filter(a => !a.synced);
  const unsyncedSales = state.sales.filter(s => !s.synced);
  const unsyncedCash = state.cashMovements.filter(c => !c.synced);

  if (unsyncedActivities.length === 0 && unsyncedSales.length === 0 && unsyncedCash.length === 0) {
    return;
  }

  setState((prev: AppState) => ({ ...prev, isSyncing: true }));

  try {
    // Dans une app réelle, on enverrait tout ça par lot (batch)
    if (unsyncedActivities.length > 0) await mockApiCall(unsyncedActivities);
    if (unsyncedSales.length > 0) await mockApiCall(unsyncedSales);
    if (unsyncedCash.length > 0) await mockApiCall(unsyncedCash);

    // Marquer comme synchronisé localement
    setState((prev: AppState) => ({
      ...prev,
      isSyncing: false,
      activities: prev.activities.map(a => ({ ...a, synced: true })),
      sales: prev.sales.map(s => ({ ...s, synced: true })),
      cashMovements: prev.cashMovements.map(c => ({ ...c, synced: true }))
    }));

    console.log("Synchronisation terminée avec succès.");
  } catch (error) {
    console.error("Échec de la synchronisation:", error);
    setState((prev: AppState) => ({ ...prev, isSyncing: false }));
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserRole, AppState, Activity, Sale, CashMovement, Notification } from './types';
import { TRANSLATIONS } from './constants';
import Dashboard from './components/Dashboard';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Login from './components/Login';
import ActivityModule from './components/ActivityModule';
import SalesModule from './components/SalesModule';
import CashModule from './components/CashModule';
import StatsModule from './components/StatsModule';
import UserManagement from './components/UserManagement';
import ChatBot from './components/ChatBot';
import TutorialModule from './components/TutorialModule';
import ProductionModule from './components/ProductionModule';
import { syncDataWithServer } from './syncService';

const INITIAL_USERS: User[] = [
  { id: '1', username: 'admin', role: UserRole.ADMIN, password: 'admin', plantationId: 'BST-001' },
  { id: '2', username: 'worker', role: UserRole.EMPLOYEE, password: 'worker', plantationId: 'BST-001' }
];

const App: React.FC = () => {
  const getTabFromHash = () => window.location.hash.replace('#', '') || 'dashboard';

  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('plameraie_state_saas');
    if (saved) {
        return JSON.parse(saved);
    }
    return {
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      notifications: [],
      language: 'FR',
      theme: 'light',
      isOnline: navigator.onLine,
      isSyncing: false
    };
  });

  const [activeTab, setActiveTab] = useState<string>(getTabFromHash());
  const [searchQuery, setSearchQuery] = useState('');

  // Détection de connexion
  useEffect(() => {
    const handleOnline = () => setState(prev => ({ ...prev, isOnline: true }));
    const handleOffline = () => setState(prev => ({ ...prev, isOnline: false }));
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Synchronisation automatique quand on revient en ligne
  useEffect(() => {
    if (state.isOnline && !state.isSyncing) {
      syncDataWithServer(state, setState);
    }
  }, [state.isOnline, state.activities, state.sales, state.cashMovements]);

  useEffect(() => {
    localStorage.setItem('plameraie_state_saas', JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    if (state.theme === 'dark') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [state.theme]);

  useEffect(() => {
    const handleHashChange = () => setActiveTab(getTabFromHash());
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const t = TRANSLATIONS[state.language];

  // FILTRAGE DES DONNÉES PAR PLANTATION (Multi-Propriétaire)
  const filteredActivities = useMemo(() => 
    state.activities.filter(a => a.plantationId === state.currentUser?.plantationId),
  [state.activities, state.currentUser]);

  const filteredSales = useMemo(() => 
    state.sales.filter(s => s.plantationId === state.currentUser?.plantationId),
  [state.sales, state.currentUser]);

  const filteredCash = useMemo(() => 
    state.cashMovements.filter(c => c.plantationId === state.currentUser?.plantationId),
  [state.cashMovements, state.currentUser]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
    addNotification('INFO', `${t.login} : ${user.username}`);
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    window.location.hash = '';
  };

  const addNotification = (type: Notification['type'], message: string) => {
    const newNotif: Notification = {
      id: Date.now().toString(),
      type,
      message,
      date: new Date().toLocaleString(),
      isRead: false
    };
    setState(prev => ({
      ...prev,
      notifications: [newNotif, ...prev.notifications].slice(0, 50)
    }));
  };

  const addActivity = (activity: Omit<Activity, 'id' | 'plantationId' | 'updatedAt'>) => {
    const newActivity: Activity = { 
      ...activity, 
      id: Date.now().toString(), 
      plantationId: state.currentUser!.plantationId,
      updatedAt: Date.now(),
      synced: false
    };

    setState(prev => ({
        ...prev,
        activities: [newActivity, ...prev.activities],
        cashMovements: activity.cost > 0 ? [
            {
              id: `cm-${Date.now()}`,
              plantationId: state.currentUser!.plantationId,
              date: activity.date,
              type: 'OUT' as const,
              amount: activity.cost,
              reason: `${activity.label} (${activity.zone})`,
              updatedAt: Date.now(),
              synced: false
            },
            ...prev.cashMovements
          ] : prev.cashMovements
    }));

    addNotification('SUCCESS', `${t[activity.type.toLowerCase()]} : ${activity.label}`);
  };

  const addSale = (sale: Omit<Sale, 'id' | 'plantationId' | 'updatedAt'>) => {
    const newSale: Sale = { 
        ...sale, 
        id: Date.now().toString(), 
        plantationId: state.currentUser!.plantationId,
        updatedAt: Date.now(),
        synced: false
    };
    setState(prev => ({
      ...prev,
      sales: [newSale, ...prev.sales],
      cashMovements: [
        {
          id: `cm-s-${Date.now()}`,
          plantationId: state.currentUser!.plantationId,
          date: sale.date,
          type: 'IN' as const,
          amount: sale.total,
          reason: `Vente: ${sale.product}`,
          updatedAt: Date.now(),
          synced: false
        },
        ...prev.cashMovements
      ]
    }));
    addNotification('SUCCESS', `${t.sales} : ${sale.product}`);
  };

  if (!state.currentUser) {
    return (
      <Login 
        onLogin={handleLogin} 
        users={state.users} 
        t={t} 
        theme={state.theme} 
        language={state.language}
        onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))}
        onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))}
      />
    );
  }

  const renderContent = () => {
    const scopedState = { ...state, activities: filteredActivities, sales: filteredSales, cashMovements: filteredCash };
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={scopedState} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={scopedState} onAdd={addActivity} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={scopedState} onAdd={addActivity} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={scopedState} onAdd={addActivity} t={t} />;
      case 'production': return <ProductionModule state={scopedState} onAdd={addActivity} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={scopedState} onAdd={addActivity} t={t} />;
      case 'sales': return <SalesModule state={scopedState} onAdd={addSale} t={t} />;
      case 'cash': return <CashModule state={scopedState} t={t} />;
      case 'stats': return <StatsModule state={scopedState} t={t} />;
      case 'users': return <UserManagement state={state} setState={setState} t={t} />;
      case 'tutorial': return <TutorialModule t={t} />;
      default: return <Dashboard state={scopedState} t={t} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={tab => window.location.hash = tab} 
        userRole={state.currentUser.role} 
        t={t} 
        onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">
        {/* Barre d'état Offline/Sync */}
        <div className={`h-1 w-full absolute top-0 z-50 transition-all duration-1000 ${state.isSyncing ? 'bg-amber-500 animate-pulse' : state.isOnline ? 'bg-green-500' : 'bg-red-500'}`} />
        {!state.isOnline && (
          <div className="bg-red-500 text-white text-[10px] font-bold py-1 px-4 text-center uppercase tracking-widest">
            Mode Hors-ligne - Les données seront synchronisées plus tard
          </div>
        )}

        <Header 
          t={t} theme={state.theme} language={state.language} 
          onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))}
          onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))}
          searchQuery={searchQuery} setSearchQuery={setSearchQuery}
          user={state.currentUser} notifications={state.notifications}
          markAllRead={() => setState(p => ({ ...p, notifications: p.notifications.map(n => ({ ...n, isRead: true })) }))}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>

      <ChatBot state={state} t={t} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { User, UserRole } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  users: User[];
  t: any;
  theme: string;
  language: string;
  onThemeToggle: () => void;
  onLanguageToggle: () => void;
}

const Login: React.FC<LoginProps> = ({ 
  onLogin, users, t, theme, language, onThemeToggle, onLanguageToggle 
}) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [plantationCode, setPlantationCode] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulation SaaS: On vérifie si l'user existe dans les comptes locaux ou si c'est un nouveau proprio
    const user = users.find(u => 
        u.username === username && 
        u.password === password && 
        u.role === role &&
        (plantationCode === '' || u.plantationId === plantationCode)
    );

    if (user) {
      onLogin(user);
    } else {
      setError("Identifiants ou Code Plantation invalide.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 px-4 transition-colors">
      <div className="absolute top-4 right-4 flex space-x-2">
        <button onClick={onLanguageToggle} className="p-2 text-sm font-bold dark:text-white">{language}</button>
        <button onClick={onThemeToggle} className="p-2 text-xl">{theme === 'light' ? '🌙' : '☀️'}</button>
      </div>

      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-green-700 rounded-3xl shadow-xl text-4xl text-white font-bold mb-4">
            P
          </div>
          <h1 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight">Plameraie BST</h1>
          <p className="text-slate-500 dark:text-slate-400 mt-2">Solution SaaS de Gestion Agricole</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-xl border border-slate-100 dark:border-slate-700">
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="flex bg-slate-100 dark:bg-slate-700 p-1 rounded-xl">
              <button 
                type="button" onClick={() => setRole(UserRole.ADMIN)}
                className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${role === UserRole.ADMIN ? 'bg-white dark:bg-slate-600 shadow-sm text-green-700 dark:text-green-300' : 'text-slate-400'}`}
              >
                {t.admin}
              </button>
              <button 
                type="button" onClick={() => setRole(UserRole.EMPLOYEE)}
                className={`flex-1 py-2 text-sm font-bold rounded-lg transition-all ${role === UserRole.EMPLOYEE ? 'bg-white dark:bg-slate-600 shadow-sm text-green-700 dark:text-green-300' : 'text-slate-400'}`}
              >
                {t.employee}
              </button>
            </div>

            <div className="space-y-1">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">Code Plantation</label>
              <input 
                type="text" value={plantationCode} onChange={e => setPlantationCode(e.target.value.toUpperCase())}
                placeholder="Ex: BST-001"
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500"
              />
            </div>

            <div className="space-y-1">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">{t.username}</label>
              <input 
                type="text" value={username} onChange={e => setUsername(e.target.value)} required
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500"
              />
            </div>

            <div className="space-y-1">
              <label className="text-xs font-black text-slate-500 uppercase tracking-widest ml-1">{t.password}</label>
              <input 
                type="password" value={password} onChange={e => setPassword(e.target.value)} required
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500"
              />
            </div>

            {error && <p className="text-red-500 text-xs font-bold text-center animate-pulse">{error}</p>}

            <button 
              type="submit"
              className="w-full bg-green-700 hover:bg-green-800 text-white font-bold py-4 rounded-xl shadow-lg transition-transform active:scale-95 mt-2"
            >
              Démarrer ma session
            </button>
          </form>

          <div className="mt-8 pt-4 border-t border-slate-100 dark:border-slate-700 flex flex-col items-center space-y-2">
            <div className="flex items-center space-x-2">
                <span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span>
                <span className="text-[10px] text-slate-400 font-bold uppercase">Système Prêt pour l'Usage Hors-ligne</span>
            </div>
            <p className="text-center text-[10px] text-slate-400">
              Chaque modification est sauvegardée localement et synchronisée dès qu'une connexion est disponible.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

