import TutorialModule from './components/TutorialModule';
import ProductionModule from './components/ProductionModule';
import SuperAdminModule from './components/SuperAdminModule';
import { syncDataWithServer } from './syncService';

// CONFIGURATION DES COMPTES PAR DÉFAUT
const INITIAL_USERS: User[] = [
  // TON COMPTE SUPER-ADMIN (Vendeur)
  { id: 'master-01', username: 'MiguelF', role: UserRole.SUPER_ADMIN, password: 'MF-05', plantationId: 'SYSTEM' },

  // COMPTE DE TEST POUR LA PREMIÈRE ENTREPRISE CLIENTE
  { id: 'admin-bst', username: 'admin', role: UserRole.ADMIN, password: 'admin', plantationId: 'BST-001' },
  { id: 'worker-bst', username: 'worker', role: UserRole.EMPLOYEE, password: 'worker', plantationId: 'BST-001' }
];

const INITIAL_PLANTATIONS: Plantation[] = [
  { id: 'BST-001', name: 'Plameraie de Démo BST', ownerName: 'Client Démo', contactEmail: 'demo@palmeraie.com', status: 'ACTIVE', expiryDate: '2026-01-01' }
];

const App: React.FC = () => {
  const getTabFromHash = () => window.location.hash.replace('#', '') || 'dashboard';

  // INITIALISATION DE LA "BASE DE DONNÉES" LOCALE
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('plameraie_db_v3');
    if (saved) return JSON.parse(saved);
    return {
      plantations: INITIAL_PLANTATIONS,
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      notifications: [],
      language: 'FR',
      theme: 'light',
      isOnline: navigator.onLine,
      isSyncing: false
    };
  });

  const [activeTab, setActiveTab] = useState<string>(getTabFromHash());
  const [searchQuery, setSearchQuery] = useState('');

  // SAUVEGARDE AUTOMATIQUE DANS LA BD LOCALE
  useEffect(() => {
    localStorage.setItem('plameraie_db_v3', JSON.stringify(state));
  }, [state]);

  useEffect(() => {
    const handleOnline = () => setState(prev => ({ ...prev, isOnline: true }));
    const handleOffline = () => setState(prev => ({ ...prev, isOnline: false }));
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (state.isOnline && !state.isSyncing) syncDataWithServer(state, setState);
  }, [state.isOnline, state.activities, state.sales, state.cashMovements]);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', state.theme === 'dark');
  }, [state.theme]);

  useEffect(() => {
    const handleHashChange = () => setActiveTab(getTabFromHash());
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  const t = TRANSLATIONS[state.language];

  // LOGIQUE DE FILTRAGE DES DONNÉES (SÉCURITÉ SaaS)
  const currentPlantation = useMemo(() => 
    state.plantations.find(p => p.id === state.currentUser?.plantationId),
  [state.plantations, state.currentUser]);

  const isAccessSuspended = state.currentUser?.role !== UserRole.SUPER_ADMIN && currentPlantation?.status === 'SUSPENDED';

  const filteredActivities = useMemo(() => 
    state.activities.filter(a => a.plantationId === state.currentUser?.plantationId),
  [state.activities, state.currentUser]);

  const filteredSales = useMemo(() => 
    state.sales.filter(s => s.plantationId === state.currentUser?.plantationId),
  [state.sales, state.currentUser]);

  const filteredCash = useMemo(() => 
    state.cashMovements.filter(c => c.plantationId === state.currentUser?.plantationId),
  [state.cashMovements, state.currentUser]);

  const handleLogin = (user: User) => {
    setState(prev => ({ ...prev, currentUser: user }));
    // Si c'est un SuperAdmin, on le redirige vers sa console
    if (user.role === UserRole.SUPER_ADMIN) {
        window.location.hash = 'superadmin';
    }
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    window.location.hash = '';
  };

  const addActivity = (activity: any) => {
    if (isAccessSuspended) return;
    const newActivity = { 
        ...activity, 
        id: Date.now().toString(), 
        plantationId: state.currentUser!.plantationId, 
        updatedAt: Date.now(), 
        synced: false 
    };
    setState(prev => ({ ...prev, activities: [newActivity, ...prev.activities] }));
  };

  const renderContent = () => {
    // ÉCRAN SPÉCIAL POUR TOI (MIGUELF)
    if (state.currentUser?.role === UserRole.SUPER_ADMIN) {
        return <SuperAdminModule state={state} setState={setState} />;
    }

    // ÉCRAN POUR LES COMPTES SUSPENDUS (NON-PAIEMENT)
    if (isAccessSuspended) {
        return (
            <div className="flex flex-col items-center justify-center h-full p-8 text-center bg-white dark:bg-slate-800 rounded-3xl shadow-xl border border-red-100 dark:border-red-900/20">
                <div className="w-24 h-24 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center text-5xl mb-6">🔒</div>
                <h2 className="text-3xl font-black text-slate-800 dark:text-white">Abonnement Expiré</h2>
                <p className="text-slate-500 mt-4 max-w-md">L'accès à votre plantation <b>{currentPlantation?.name}</b> a été suspendu. Veuillez contacter <b>MiguelF</b> pour régulariser votre situation.</p>
                <div className="mt-8 p-4 bg-slate-50 dark:bg-slate-700/50 rounded-xl text-xs font-mono text-slate-400">ID Plantation: {state.currentUser?.plantationId}</div>
            </div>
        );
    }

    const scopedState = { ...state, activities: filteredActivities, sales: filteredSales, cashMovements: filteredCash };
    switch (activeTab) {
      case 'dashboard': return <Dashboard state={scopedState} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={scopedState} onAdd={addActivity} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={scopedState} onAdd={addActivity} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={scopedState} onAdd={addActivity} t={t} />;
      case 'production': return <ProductionModule state={scopedState} onAdd={addActivity} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={scopedState} onAdd={addActivity} t={t} />;
      case 'sales': return <SalesModule state={scopedState} onAdd={(s: any) => { if (!isAccessSuspended) { const ns = { ...s, id: Date.now().toString(), plantationId: state.currentUser!.plantationId, updatedAt: Date.now(), synced: false }; setState(p => ({ ...p, sales: [ns, ...p.sales] })) }}} t={t} />;
      case 'cash': return <CashModule state={scopedState} t={t} />;
      case 'stats': return <StatsModule state={scopedState} t={t} />;
      case 'users': return <UserManagement state={state} setState={setState} t={t} />;
      case 'tutorial': return <TutorialModule t={t} />;
      default: return <Dashboard state={scopedState} t={t} />;
    }
  };

  if (!state.currentUser) {
    return (
      <Login 
        onLogin={handleLogin} users={state.users} t={t} theme={state.theme} language={state.language}
        onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))}
        onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))}
      />
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      <Sidebar 
        activeTab={activeTab} setActiveTab={tab => window.location.hash = tab} 
        userRole={state.currentUser.role} t={t} onLogout={handleLogout}
      />

      <div className="flex-1 flex flex-col min-w-0 relative">
        <div className={`h-1 w-full absolute top-0 z-50 transition-all duration-1000 ${state.isSyncing ? 'bg-amber-500 animate-pulse' : state.isOnline ? 'bg-green-500' : 'bg-red-500'}`} />
        <Header 
          t={t} theme={state.theme} language={state.language} 
          onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))}
          onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))}
          searchQuery={searchQuery} setSearchQuery={setSearchQuery}
          user={state.currentUser} notifications={state.notifications}
          markAllRead={() => {}}
        />
        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          {renderContent()}
        </main>
      </div>
      <ChatBot state={state} t={t} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, Plantation, User, UserRole } from '../types';

interface SuperAdminModuleProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
}

const SuperAdminModule: React.FC<SuperAdminModuleProps> = ({ state, setState }) => {
  const [newPlantation, setNewPlantation] = useState({ name: '', owner: '', email: '' });
  const [showCode, setShowCode] = useState<string | null>(null);

  const addPlantation = (e: React.FormEvent) => {
    e.preventDefault();
    // Génère un code unique pour le client
    const id = `PALM-${Math.floor(100 + Math.random() * 899)}`;

    const plantation: Plantation = {
      id,
      name: newPlantation.name,
      ownerName: newPlantation.owner,
      contactEmail: newPlantation.email,
      status: 'ACTIVE',
      expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    };

    // On crée aussi un utilisateur "admin" par défaut pour ce code
    const defaultAdmin: User = {
        id: `user-${Date.now()}`,
        username: 'admin',
        password: 'admin',
        role: UserRole.ADMIN,
        plantationId: id
    };

    setState(prev => ({ 
        ...prev, 
        plantations: [...prev.plantations, plantation],
        users: [...prev.users, defaultAdmin]
    }));

    setShowCode(id);
    setNewPlantation({ name: '', owner: '', email: '' });
  };

  const toggleStatus = (id: string) => {
    setState(prev => ({
      ...prev,
      plantations: prev.plantations.map(p => 
        p.id === id ? { ...p, status: p.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' } : p
      )
    }));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-gradient-to-br from-slate-900 to-slate-800 text-white p-8 rounded-3xl shadow-2xl border border-slate-700">
        <div className="flex justify-between items-center">
          <div>
            <h2 className="text-3xl font-black mb-2 flex items-center">
              <span className="mr-3">👑</span> Bonjour, MiguelF
            </h2>
            <p className="text-slate-400">Bienvenue dans votre console de gestion Plameraie BST.</p>
          </div>
          <div className="bg-green-500/10 border border-green-500/20 px-4 py-2 rounded-xl">
             <span className="text-green-400 font-bold">{state.plantations.length} Entreprises Clientes</span>
          </div>
        </div>
      </div>

      {showCode && (
        <div className="bg-green-700 text-white p-6 rounded-3xl shadow-lg animate-bounce">
            <h4 className="font-bold mb-2">✅ Entreprise créée avec succès !</h4>
            <p className="text-sm opacity-90">Donnez ce code à votre client :</p>
            <div className="bg-white/20 p-4 rounded-xl mt-2 text-3xl font-black text-center tracking-widest border border-white/30">
                {showCode}
            </div>
            <p className="text-xs mt-4 italic">* Identifiants par défaut : admin / admin</p>
            <button onClick={() => setShowCode(null)} className="mt-4 text-xs underline font-bold">Fermer ce message</button>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-white dark:bg-slate-800 p-8 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-sm">
          <h3 className="text-lg font-bold mb-6 dark:text-white">Inscrire un nouveau client</h3>
          <form onSubmit={addPlantation} className="space-y-4">
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Nom de la Plantation</label>
                <input 
                    required placeholder="Ex: Palmeraie du Sud"
                    value={newPlantation.name} onChange={e => setNewPlantation({...newPlantation, name: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
                />
            </div>
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Nom du Gérant</label>
                <input 
                    required placeholder="Ex: M. Kouassi"
                    value={newPlantation.owner} onChange={e => setNewPlantation({...newPlantation, owner: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
                />
            </div>
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Email de contact</label>
                <input 
                    required type="email" placeholder="client@email.com"
                    value={newPlantation.email} onChange={e => setNewPlantation({...newPlantation, email: e.target.value})}
                    className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 dark:text-white"
                />
            </div>
            <button className="w-full bg-green-700 text-white font-bold py-4 rounded-2xl shadow-lg hover:bg-green-800 transition-all transform active:scale-95">
              Valider & Générer le Code
            </button>
          </form>
        </div>

        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-3xl border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden">
          <div className="p-6 border-b border-slate-50 dark:border-slate-700">
             <h3 className="font-bold dark:text-white">Vos Clients Actifs</h3>
          </div>
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-700/50">
              <tr>
                <th className="px-6 py-4 text-xs font-black text-slate-400 uppercase">Code Client</th>
                <th className="px-6 py-4 text-xs font-black text-slate-400 uppercase">Plantation</th>
                <th className="px-6 py-4 text-xs font-black text-slate-400 uppercase">Statut</th>
                <th className="px-6 py-4 text-xs font-black text-slate-400 uppercase">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
              {state.plantations.filter(p => p.id !== 'SYSTEM').map(p => (
                <tr key={p.id}>
                  <td className="px-6 py-4">
                    <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full font-mono font-bold text-sm">
                        {p.id}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <p className="font-bold dark:text-white">{p.name}</p>
                    <p className="text-[10px] text-slate-400">{p.ownerName} • {p.contactEmail}</p>
                  </td>
                  <td className="px-6 py-4">
                    <span className={`px-2 py-1 rounded-lg text-[10px] font-bold ${p.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                      {p.status === 'ACTIVE' ? 'PAIEMENT OK' : 'SUSPENDU'}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <button 
                        onClick={() => toggleStatus(p.id)} 
                        className={`text-xs font-bold px-4 py-2 rounded-xl border transition-all ${p.status === 'ACTIVE' ? 'border-red-200 text-red-500 hover:bg-red-50' : 'border-green-200 text-green-500 hover:bg-green-50'}`}
                    >
                      {p.status === 'ACTIVE' ? 'Désactiver le compte' : 'Réactiver'}
                    </button>
                  </td>
                </tr>
              ))}
              {state.plantations.length <= 1 && (
                  <tr>
                      <td colSpan={4} className="p-12 text-center text-slate-400 italic">Vous n'avez pas encore de client. Inscrivez votre premier client à gauche !</td>
                  </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default SuperAdminModule;

import React, { useState } from 'react';
import { User, UserRole } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  users: User[];
  t: any;
  theme: string;
  language: string;
  onThemeToggle: () => void;
  onLanguageToggle: () => void;
}

const Login: React.FC<LoginProps> = ({ 
  onLogin, users, t, theme, language, onThemeToggle, onLanguageToggle 
}) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [plantationCode, setPlantationCode] = useState('');
  const [role, setRole] = useState<UserRole>(UserRole.ADMIN);
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    // Pour le SuperAdmin MiguelF, on force le code SYSTEM s'il ne l'a pas mis
    const checkCode = (username === 'MiguelF') ? 'SYSTEM' : plantationCode;

    const user = users.find(u => 
        u.username === username && 
        u.password === password && 
        (checkCode === '' || u.plantationId === checkCode)
    );

    if (user) {
      onLogin(user);
    } else {
      setError("Identifiants ou Code Plantation incorrect.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 px-4 transition-colors">
      <div className="absolute top-4 right-4 flex space-x-2">
        <button onClick={onLanguageToggle} className="p-2 text-sm font-bold dark:text-white border border-slate-200 dark:border-slate-700 rounded-xl">{language}</button>
        <button onClick={onThemeToggle} className="p-2 text-xl">{theme === 'light' ? '🌙' : '☀️'}</button>
      </div>

      <div className="w-full max-w-md">
        <div className="text-center mb-8 animate-in fade-in duration-1000">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-green-700 rounded-3xl shadow-xl text-4xl text-white font-bold mb-4 transform hover:rotate-12 transition-transform">
            P
          </div>
          <h1 className="text-3xl font-black text-slate-800 dark:text-white tracking-tight">Plameraie BST</h1>
          <p className="text-slate-500 dark:text-slate-400 mt-2">Gestion Intelligente de Plantation</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-3xl shadow-2xl border border-slate-100 dark:border-slate-700">
          <form onSubmit={handleLogin} className="space-y-4">
            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Code Plantation</label>
              <input 
                type="text" value={plantationCode} onChange={e => setPlantationCode(e.target.value.toUpperCase())}
                placeholder="Ex: BST-001 (ou SYSTEM pour MiguelF)"
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500 transition-all"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Utilisateur</label>
              <input 
                type="text" value={username} onChange={e => setUsername(e.target.value)} required
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500 transition-all"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Mot de passe</label>
              <input 
                type="password" value={password} onChange={e => setPassword(e.target.value)} required
                className="w-full px-4 py-3 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-xl outline-none dark:text-white focus:ring-2 focus:ring-green-500 transition-all"
              />
            </div>

            {error && <p className="text-red-500 text-xs font-bold text-center bg-red-50 dark:bg-red-900/10 py-2 rounded-lg">{error}</p>}

            <button 
              type="submit"
              className="w-full bg-green-700 hover:bg-green-800 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-95 mt-2"
            >
              Accéder au Système
            </button>
          </form>

          <div className="mt-8 pt-6 border-t border-slate-100 dark:border-slate-700 text-center">
            <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">Technologie Plameraie BST</p>
            <p className="text-[10px] text-slate-400 mt-1 italic">Entièrement fonctionnel sans connexion internet.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState } from 'react';
import { UserRole } from '../types';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: string) => void;
  userRole: UserRole;
  t: any;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, userRole, t, onLogout }) => {
  const [isOpen, setIsOpen] = useState(false);

  // Définition des accès : certains menus sont réservés aux ADMIN ou SUPER_ADMIN
  const menuItems = [
    { id: 'dashboard', label: t.dashboard, icon: '📊', restricted: false },
    { id: 'creation', label: t.creation, icon: '🌱', restricted: false },
    { id: 'maintenance', label: t.maintenance, icon: '🛠️', restricted: false },
    { id: 'harvest', label: t.harvest, icon: '🚜', restricted: false },
    { id: 'production', label: t.production, icon: '🏭', restricted: false },
    { id: 'packaging', label: t.packaging, icon: '📦', restricted: false },
    { id: 'sales', label: t.sales, icon: '💰', restricted: false },
    { id: 'cash', label: t.cash, icon: '🏦', restricted: true }, // Caché pour employé
    { id: 'stats', label: t.stats, icon: '📈', restricted: true }, // Caché pour employé
    { id: 'tutorial', label: t.tutorial, icon: '🎓', restricted: false },
    { id: 'users', label: t.users, icon: '👥', restricted: true }, // Caché pour employé
  ];

  // Un employé ne peut voir que les menus non-restreints
  const filteredItems = menuItems.filter(item => {
    if (userRole === UserRole.SUPER_ADMIN) return true;
    if (userRole === UserRole.ADMIN) return true;
    return !item.restricted; // Si c'est un EMPLOYEE, on ne garde que les non-restreints
  });

  return (
    <>
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="fixed bottom-4 left-4 z-50 md:hidden bg-green-700 text-white p-3 rounded-full shadow-lg"
      >
        {isOpen ? '✕' : '☰'}
      </button>

      <aside className={`
        fixed inset-y-0 left-0 z-40 w-64 bg-white dark:bg-slate-800 border-r border-slate-200 dark:border-slate-700
        transform transition-transform duration-200 ease-in-out md:relative md:translate-x-0
        ${isOpen ? 'translate-x-0' : '-translate-x-full'}
      `}>
        <div className="h-full flex flex-col p-4">
          <div className="flex items-center space-x-2 px-2 py-6 mb-4">
