import React, { useState } from 'react';
import { AppState, Plantation, User, UserRole } from '../types';

interface SuperAdminModuleProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  t: any;
}

const SuperAdminModule: React.FC<SuperAdminModuleProps> = ({ state, setState, t }) => {
  const [newPlantation, setNewPlantation] = useState({ name: '', owner: '', email: '' });
  const [showCode, setShowCode] = useState<string | null>(null);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const saT = t.superAdmin;

  const addPlantation = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `PALM-${Math.floor(100 + Math.random() * 899)}`;

    const plantation: Plantation = {
      id,
      name: newPlantation.name,
      ownerName: newPlantation.owner,
      contactEmail: newPlantation.email,
      status: 'ACTIVE',
      expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    };

    const defaultAdmin: User = {
        id: `user-${Date.now()}`,
        username: 'admin',
        password: 'admin',
        role: UserRole.ADMIN,
        plantationId: id
    };

    setState(prev => ({ 
        ...prev, 
        plantations: [...prev.plantations, plantation],
        users: [...prev.users, defaultAdmin]
    }));

    setShowCode(id);
    setNewPlantation({ name: '', owner: '', email: '' });
  };

  const handleUpdateCreds = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === editingUser.id ? editingUser : u)
    }));
    setEditingUser(null);
    alert("Identifiants mis à jour !");
  };

  const toggleStatus = (id: string) => {
    setState(prev => ({
      ...prev,
      plantations: prev.plantations.map(p => 
        p.id === id ? { ...p, status: p.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' } : p
      )
    }));
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="bg-gradient-to-br from-slate-900 via-slate-800 to-green-900 text-white p-10 rounded-[3rem] shadow-2xl border border-slate-700 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-white/5 rounded-full -mr-32 -mt-32 blur-3xl"></div>
        <div className="relative z-10 flex justify-between items-center">
          <div>
            <h2 className="text-4xl font-black mb-2 flex items-center tracking-tighter">
              <span className="mr-4">👑</span> {saT.hello}
            </h2>
            <p className="text-slate-400 font-medium">Contrôle total des accès Plameraie BST</p>
          </div>
          <div className="bg-white/10 backdrop-blur-md border border-white/20 px-6 py-3 rounded-2xl">
             <span className="text-green-400 font-black text-lg">{state.plantations.length - 1} {saT.clientCount}</span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Inscription */}
        <div className="lg:col-span-1 bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm">
          <h3 className="text-xl font-black mb-6 text-slate-800 dark:text-white flex items-center">
            <span className="mr-2">📝</span> {saT.newClient}
          </h3>
          <form onSubmit={addPlantation} className="space-y-5">
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 ml-1 block">{saT.plantationName}</label>
                <input required placeholder="Ex: Palmeraie du Sud" value={newPlantation.name} onChange={e => setNewPlantation({...newPlantation, name: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 text-slate-800 dark:text-white font-bold transition-all" />
            </div>
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 ml-1 block">{saT.managerName}</label>
                <input required placeholder="Ex: M. Kouassi" value={newPlantation.owner} onChange={e => setNewPlantation({...newPlantation, owner: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 text-slate-800 dark:text-white font-bold transition-all" />
            </div>
            <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 ml-1 block">{saT.email}</label>
                <input required type="email" placeholder="client@email.com" value={newPlantation.email} onChange={e => setNewPlantation({...newPlantation, email: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none focus:ring-2 focus:ring-green-500 text-slate-800 dark:text-white font-bold transition-all" />
            </div>
            <button className="w-full bg-green-700 text-white font-black py-5 rounded-2xl shadow-lg hover:bg-green-800 transition-all transform active:scale-95 uppercase tracking-widest text-xs">
              {saT.generate}
            </button>
          </form>
        </div>

        {/* Liste des Clients */}
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm overflow-hidden flex flex-col">
          <div className="p-8 border-b border-slate-50 dark:border-slate-700">
             <h3 className="text-xl font-black text-slate-800 dark:text-white flex items-center">
              <span className="mr-2">📋</span> {saT.activeClients}
             </h3>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-left">
              <thead className="bg-slate-50 dark:bg-slate-700/50">
                <tr>
                  <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">{saT.clientCode}</th>
                  <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Entreprise</th>
                  <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Identifiants Admin</th>
                  <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Status</th>
                  <th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
                {state.plantations.filter(p => p.id !== 'SYSTEM').map(p => {
                  const adminUser = state.users.find(u => u.plantationId === p.id && u.role === UserRole.ADMIN);
                  return (
                    <tr key={p.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
                      <td className="px-6 py-4">
                        <span className="bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400 px-4 py-1.5 rounded-full font-mono font-black text-sm">{p.id}</span>
                      </td>
                      <td className="px-6 py-4">
                        <p className="font-black text-slate-800 dark:text-white">{p.name}</p>
                        <p className="text-[10px] text-slate-400 font-bold uppercase">{p.ownerName}</p>
                      </td>
                      <td className="px-6 py-4">
                        {adminUser ? (
                          <div className="space-y-1">
                            <p className="text-xs font-bold dark:text-slate-300">User: <span className="text-green-600">{adminUser.username}</span></p>
                            <p className="text-xs font-bold dark:text-slate-300">Pass: <span className="text-green-600">{adminUser.password}</span></p>
                            <button onClick={() => setEditingUser(adminUser)} className="text-[10px] font-black text-blue-500 uppercase hover:underline">Modifier</button>
                          </div>
                        ) : <span className="text-xs text-red-400 italic">Aucun Admin</span>}
                      </td>
                      <td className="px-6 py-4">
                        <span className={`px-3 py-1 rounded-xl text-[10px] font-black tracking-widest ${p.status === 'ACTIVE' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
                          {p.status === 'ACTIVE' ? 'OK' : 'OFF'}
                        </span>
                      </td>
                      <td className="px-6 py-4">
                        <button onClick={() => toggleStatus(p.id)} className={`text-[10px] font-black px-4 py-2 rounded-xl border-2 transition-all uppercase tracking-widest ${p.status === 'ACTIVE' ? 'border-red-100 text-red-500 hover:bg-red-50' : 'border-green-100 text-green-500 hover:bg-green-50'}`}>
                          {p.status === 'ACTIVE' ? saT.suspend : saT.reactivate}
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {/* Modal Modification Identifiants */}
      {editingUser && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
           <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 border border-slate-100 dark:border-slate-700">
              <h3 className="text-xl font-black mb-6 dark:text-white">Identifiants Client</h3>
              <form onSubmit={handleUpdateCreds} className="space-y-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Nom Utilisateur</label>
                  <input required value={editingUser.username} onChange={e => setEditingUser({...editingUser, username: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 rounded-2xl outline-none dark:text-white font-bold" />
                </div>
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase mb-1 block">Mot de passe</label>
                  <input required value={editingUser.password} onChange={e => setEditingUser({...editingUser, password: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 rounded-2xl outline-none dark:text-white font-bold" />
                </div>
                <div className="flex space-x-3 pt-4">
                  <button type="button" onClick={() => setEditingUser(null)} className="flex-1 py-4 bg-slate-100 text-slate-500 rounded-2xl font-black uppercase text-[10px]">Annuler</button>
                  <button type="submit" className="flex-1 py-4 bg-green-700 text-white rounded-2xl font-black uppercase text-[10px]">Enregistrer</button>
                </div>
              </form>
           </div>
        </div>
      )}

      {showCode && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-green-900/60 backdrop-blur-xl">
            <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl text-center max-w-sm w-full animate-in zoom-in duration-300">
                <div className="w-20 h-20 bg-green-100 text-green-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-6">✅</div>
                <h4 className="text-2xl font-black mb-2 dark:text-white">{saT.success}</h4>
