                   <p className="text-[10px] text-amber-700 font-black uppercase">Identifiants par défaut</p>
                   <p className="text-sm font-bold dark:text-white">User: admin / Pass: admin</p>
                </div>
                <button onClick={() => setShowCode(null)} className="w-full py-5 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest text-xs">J'ai compris</button>
            </div>
        </div>
      )}
