        </div>

        <div className="h-8 w-px bg-slate-100 dark:bg-slate-700 mx-1 hidden sm:block"></div>

        <div className="flex items-center space-x-3 bg-slate-50 dark:bg-slate-700/50 pl-3 pr-1 py-1 rounded-2xl border border-slate-100 dark:border-slate-600">
