export default App;

import React, { useState } from 'react';
import { User } from '../types';

interface LoginProps {
  onLogin: (user: User) => void;
  users: User[];
  t: any;
  theme: string;
  language: string;
  onThemeToggle: () => void;
  onLanguageToggle: () => void;
}

const Login: React.FC<LoginProps> = ({ 
  onLogin, users, t, theme, language, onThemeToggle, onLanguageToggle 
}) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [plantationCode, setPlantationCode] = useState('');
  const [error, setError] = useState('');

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    const checkCode = (username === 'MiguelF') ? 'SYSTEM' : plantationCode;
    const user = users.find(u => 
        u.username.toLowerCase() === username.toLowerCase() && 
        u.password === password && 
        (checkCode === '' || u.plantationId === checkCode)
    );

    if (user) {
      onLogin(user);
    } else {
      setError("Identifiants ou Code Plantation incorrect.");
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50 dark:bg-slate-900 px-4 transition-colors">
      <div className="absolute top-6 right-6 flex space-x-3">
        <button onClick={onLanguageToggle} className="px-4 py-2 text-xs font-black dark:text-white border border-slate-200 dark:border-slate-700 rounded-2xl bg-white/50 dark:bg-slate-800/50 backdrop-blur-sm shadow-sm uppercase tracking-widest">{language}</button>
        <button onClick={onThemeToggle} className="p-3 text-xl bg-white/50 dark:bg-slate-800/50 rounded-2xl shadow-sm">{theme === 'light' ? '🌙' : '☀️'}</button>
      </div>

      <div className="w-full max-w-md animate-in fade-in zoom-in duration-500">
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-24 h-24 bg-gradient-to-br from-green-600 to-green-800 rounded-[2.5rem] shadow-2xl text-4xl text-white font-black mb-6 transform hover:rotate-12 transition-transform">
            P
          </div>
          <h1 className="text-4xl font-black text-slate-800 dark:text-white tracking-tighter">Plameraie BST</h1>
          <p className="text-slate-500 dark:text-slate-400 font-medium mt-2">Accès sécurisé à votre gestion</p>
        </div>

        <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-[0_32px_64px_-16px_rgba(0,0,0,0.1)] border border-slate-100 dark:border-slate-700 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-green-500 via-amber-500 to-green-500"></div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Code Plantation</label>
              <input 
                type="text" value={plantationCode} onChange={e => setPlantationCode(e.target.value.toUpperCase())}
                placeholder="Ex: PALM-123"
                className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-100 dark:border-slate-600 rounded-2xl outline-none dark:text-white focus:ring-4 focus:ring-green-500/10 focus:border-green-500 transition-all font-bold"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Utilisateur</label>
              <input 
                type="text" value={username} onChange={e => setUsername(e.target.value)} required
                className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-100 dark:border-slate-600 rounded-2xl outline-none dark:text-white focus:ring-4 focus:ring-green-500/10 focus:border-green-500 transition-all font-bold"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">Mot de passe</label>
              <input 
                type="password" value={password} onChange={e => setPassword(e.target.value)} required
                className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-100 dark:border-slate-600 rounded-2xl outline-none dark:text-white focus:ring-4 focus:ring-green-500/10 focus:border-green-500 transition-all font-bold"
              />
            </div>

            {error && (
              <div className="p-4 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-800 rounded-2xl">
                <p className="text-red-600 dark:text-red-400 text-xs font-black text-center">{error}</p>
              </div>
            )}

            <button 
              type="submit"
              className="w-full bg-green-700 hover:bg-green-800 text-white font-black py-5 rounded-2xl shadow-xl shadow-green-900/20 transition-all transform active:scale-95 uppercase tracking-widest text-xs"
            >
              Se Connecter
            </button>
          </form>
        </div>

        <p className="text-center mt-8 text-slate-400 text-[10px] font-black uppercase tracking-widest">Plameraie BST © 2024</p>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef, useEffect } from 'react';
import { User, Notification } from '../types';

interface HeaderProps {
  t: any;
  theme: 'light' | 'dark';
  language: 'FR' | 'EN';
  onThemeToggle: () => void;
  onLanguageToggle: () => void;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  user: User;
  notifications: Notification[];
  markAllRead: () => void;
  onHelpClick: () => void;
}

const Header: React.FC<HeaderProps> = ({ 
  t, theme, language, onThemeToggle, onLanguageToggle, searchQuery, setSearchQuery, user, notifications, markAllRead, onHelpClick 
}) => {
  const [showNotifs, setShowNotifs] = useState(false);
  const unreadCount = notifications.filter(n => !n.isRead).length;
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowNotifs(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <header className="sticky top-0 z-[60] flex items-center justify-between bg-white/90 dark:bg-slate-800/90 backdrop-blur-xl px-4 md:px-8 py-3 border-b border-slate-100 dark:border-slate-700 transition-all">
      <div className="flex-1 max-w-[150px] md:max-w-md hidden sm:block">
        <div className="relative">
          <span className="absolute inset-y-0 left-0 pl-3 flex items-center text-slate-400">🔍</span>
          <input
            type="text"
            placeholder={t.searchPlaceholder}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-10 pr-4 py-2 bg-slate-50 dark:bg-slate-700/50 border-none rounded-2xl focus:ring-2 focus:ring-green-500/20 text-sm dark:text-white transition-all"
          />
        </div>
      </div>

      <div className="flex items-center space-x-2 md:space-x-4 ml-auto">
        <button 
          onClick={onHelpClick}
          className="p-2.5 rounded-xl hover:bg-slate-50 dark:hover:bg-slate-700/50 text-amber-600 transition-all font-black text-[10px] uppercase tracking-widest flex items-center space-x-1"
        >
          <span className="text-lg">🎓</span> <span className="hidden xs:inline">Aide</span>
        </button>

        <div className="relative" ref={dropdownRef}>
          <button 
            onClick={() => setShowNotifs(!showNotifs)} 
            className={`p-2.5 rounded-xl transition-all relative border ${unreadCount > 0 ? 'bg-red-50 border-red-100 text-red-600 dark:bg-red-900/20 dark:border-red-800' : 'bg-slate-50 dark:bg-slate-700/50 dark:text-slate-400'}`}
          >
            <span className="text-xl">🔔</span>
            {unreadCount > 0 && <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-600 text-white text-[10px] font-black flex items-center justify-center rounded-full border-2 border-white dark:border-slate-800 animate-bounce">{unreadCount}</span>}
          </button>

          {showNotifs && (
            <div className="fixed sm:absolute right-4 left-4 sm:left-auto top-16 sm:top-full mt-2 sm:w-80 bg-white dark:bg-slate-800 rounded-[2rem] shadow-2xl border border-slate-100 dark:border-slate-700 overflow-hidden animate-in fade-in slide-in-from-top-2 z-[70]">
              <div className="p-5 border-b border-slate-50 dark:border-slate-700 flex justify-between items-center bg-slate-50/50 dark:bg-slate-900/20">
                <h3 className="font-black text-slate-800 dark:text-white uppercase tracking-widest text-[10px]">{t.notifications}</h3>
                {unreadCount > 0 && <button onClick={markAllRead} className="text-[10px] text-green-600 font-black uppercase">{t.markAllRead}</button>}
              </div>
              <div className="max-h-[50vh] sm:max-h-[350px] overflow-y-auto custom-scrollbar">
                {notifications.length === 0 ? (
                    <div className="p-10 text-center text-slate-400 text-xs italic">{t.noNotifications}</div>
                ) : (
                  notifications.map(notif => (
                    <div key={notif.id} className={`p-4 border-b border-slate-50 dark:border-slate-700/50 flex space-x-3 ${!notif.isRead ? 'bg-green-50/20' : 'opacity-60'}`}>
                      <div className="text-xl">{notif.type === 'SUCCESS' ? '✅' : notif.type === 'ALERT' ? '🚨' : 'ℹ️'}</div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-bold text-slate-800 dark:text-slate-200 leading-tight">{notif.message}</p>
                        <p className="text-[9px] font-black text-slate-400 uppercase mt-1">{notif.date}</p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          )}
        </div>

        <div className="flex items-center space-x-2 bg-slate-50 dark:bg-slate-700/50 p-1.5 rounded-2xl border border-slate-100 dark:border-slate-600">
          <div className="hidden md:block text-right mr-2">
            <p className="text-[10px] font-black text-slate-800 dark:text-white leading-tight uppercase tracking-tight">{user.username}</p>
            <p className="text-[8px] text-slate-400 uppercase font-black">{user.role}</p>
          </div>
          <div className="w-8 h-8 rounded-xl bg-gradient-to-br from-green-600 to-green-800 text-white flex items-center justify-center font-black shadow-md">
            {user.username.charAt(0).toUpperCase()}
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

import React, { useState } from 'react';
import { AppState, Plantation, User, UserRole } from '../types';

interface SuperAdminModuleProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  t: any;
}

const SuperAdminModule: React.FC<SuperAdminModuleProps> = ({ state, setState, t }) => {
  const [newPlantation, setNewPlantation] = useState({ name: '', owner: '', email: '' });
  const [showCode, setShowCode] = useState<string | null>(null);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  const saT = t.superAdmin;

  const generateShareLink = (pId: string) => {
    const p = state.plantations.find(pl => pl.id === pId);
    const companyUsers = state.users.filter(u => u.plantationId === pId);
    const config = { plantations: [p], users: companyUsers };
    const base64 = btoa(unescape(encodeURIComponent(JSON.stringify(config))));
    const url = `${window.location.origin}${window.location.pathname}?config=${base64}`;

    navigator.clipboard.writeText(url);
    alert("🔗 Lien d'activation copié ! Envoyez-le au client.");
  };

  const addPlantation = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `PALM-${Math.floor(100 + Math.random() * 899)}`;
    const plantation: Plantation = {
      id, name: newPlantation.name, ownerName: newPlantation.owner, contactEmail: newPlantation.email,
      status: 'ACTIVE', expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    };
    const defaultAdmin: User = { id: `user-${Date.now()}`, username: 'admin', password: 'admin', role: UserRole.ADMIN, plantationId: id };

    setState(prev => ({ ...prev, plantations: [...prev.plantations, plantation], users: [...prev.users, defaultAdmin] }));
    setShowCode(id);
    setNewPlantation({ name: '', owner: '', email: '' });
  };

  const handleUpdateCreds = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      setState(prev => ({ ...prev, users: prev.users.map(u => u.id === editingUser.id ? editingUser : u) }));
      setEditingUser(null);
      alert("Identifiants mis à jour !");
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-slate-900 text-white p-8 rounded-[2.5rem] shadow-2xl relative overflow-hidden">
        <h2 className="text-3xl font-black mb-1">👑 Bonjour, MiguelF</h2>
        <p className="text-slate-400 text-sm">Gestionnaire Maître Plameraie BST</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-700">
          <h3 className="text-xl font-black mb-6 dark:text-white">Inscrire un Client</h3>
          <form onSubmit={addPlantation} className="space-y-4">
            <input required placeholder="Nom de la Palmeraie" value={newPlantation.name} onChange={e => setNewPlantation({...newPlantation, name: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none dark:text-white font-bold" />
            <input required placeholder="Nom du Gérant" value={newPlantation.owner} onChange={e => setNewPlantation({...newPlantation, owner: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none dark:text-white font-bold" />
            <input required type="email" placeholder="Email de contact" value={newPlantation.email} onChange={e => setNewPlantation({...newPlantation, email: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-200 dark:border-slate-600 rounded-2xl outline-none dark:text-white font-bold" />
            <button className="w-full bg-green-700 text-white font-black py-5 rounded-2xl shadow-lg uppercase text-xs tracking-widest">Créer le Compte</button>
          </form>
        </div>

        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-700/50">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Client</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Identifiants</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
              {state.plantations.filter(p => p.id !== 'SYSTEM').map(p => {
                const admin = state.users.find(u => u.plantationId === p.id && u.role === UserRole.ADMIN);
                return (
                  <tr key={p.id} className="hover:bg-slate-50 dark:hover:bg-slate-700/30 transition-colors">
                    <td className="px-6 py-4">
                      <p className="font-black text-slate-800 dark:text-white">{p.name}</p>
                      <p className="text-[10px] text-green-600 font-mono font-black">{p.id}</p>
                    </td>
                    <td className="px-6 py-4">
                      {admin ? (
                        <button onClick={() => setEditingUser(admin)} className="text-left">
                          <p className="text-xs font-bold dark:text-slate-300">U: <span className="text-blue-500">{admin.username}</span></p>
                          <p className="text-xs font-bold dark:text-slate-300">P: <span className="text-blue-500">{admin.password}</span></p>
                        </button>
                      ) : 'N/A'}
                    </td>
                    <td className="px-6 py-4">
                      <button onClick={() => generateShareLink(p.id)} className="bg-blue-50 dark:bg-blue-900/20 text-blue-600 text-[9px] font-black px-3 py-2 rounded-xl uppercase tracking-widest">Copier Lien</button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {editingUser && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-md">
           <div className="bg-white dark:bg-slate-800 w-full max-w-sm rounded-[3rem] p-8">
              <h3 className="text-xl font-black mb-6 dark:text-white">Modifier Admin</h3>
              <form onSubmit={handleUpdateCreds} className="space-y-4">
                <input required value={editingUser.username} onChange={e => setEditingUser({...editingUser, username: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border rounded-2xl outline-none dark:text-white font-bold" />
                <input required value={editingUser.password} onChange={e => setEditingUser({...editingUser, password: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border rounded-2xl outline-none dark:text-white font-bold" />
                <button type="submit" className="w-full py-4 bg-green-700 text-white rounded-2xl font-black uppercase text-xs">Enregistrer</button>
                <button type="button" onClick={() => setEditingUser(null)} className="w-full py-4 text-slate-400 font-bold text-xs uppercase">Annuler</button>
              </form>
           </div>
        </div>
      )}

      {showCode && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-green-900/60 backdrop-blur-xl">
            <div className="bg-white dark:bg-slate-800 p-10 rounded-[3rem] shadow-2xl text-center max-w-sm w-full animate-in zoom-in">
                <h4 className="text-2xl font-black mb-2 dark:text-white">Compte Créé !</h4>
                <div className="bg-slate-50 dark:bg-slate-700 p-6 rounded-3xl mb-6 border-2 border-dashed border-green-200">
                    <p className="text-4xl font-black tracking-widest text-green-700 dark:text-green-400">{showCode}</p>
                </div>
                <button onClick={() => { generateShareLink(showCode); setShowCode(null); }} className="w-full py-5 bg-green-700 text-white rounded-2xl font-black uppercase text-xs">Copier le Lien d'Activation</button>
            </div>
        </div>
      )}
    </div>
  );
};

export default SuperAdminModule;

import React, { useState } from 'react';
import { AppState, User, UserRole } from '../types';

interface UserManagementProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  t: any;
}

const UserManagement: React.FC<UserManagementProps> = ({ state, setState, t }) => {
  const [newUser, setNewUser] = useState({ username: '', password: '', role: UserRole.EMPLOYEE });

  const filteredUsers = state.users.filter(u => u.plantationId === state.currentUser?.plantationId);

  const generateEmployeeLink = () => {
    const pId = state.currentUser?.plantationId;
    const p = state.plantations.find(pl => pl.id === pId);
    // On envoie la plantation et TOUS les utilisateurs de cette plantation pour que tout le monde soit synchrone
    const companyUsers = state.users.filter(u => u.plantationId === pId);
    const config = { plantations: [p], users: companyUsers };
    const base64 = btoa(unescape(encodeURIComponent(JSON.stringify(config))));
    const url = `${window.location.origin}${window.location.pathname}?config=${base64}`;

    navigator.clipboard.writeText(url);
    alert("🔗 Lien d'invitation copié ! Envoyez-le à vos employés pour configurer leur téléphone.");
  };

  const handleAddUser = (e: React.FormEvent) => {
    e.preventDefault();
    if (state.users.find(u => u.username === newUser.username)) return alert("Utilisateur déjà existant.");

    const user: User = { 
      id: `user-${Date.now()}`, 
      username: newUser.username, 
      password: newUser.password, 
      role: newUser.role,
      plantationId: state.currentUser?.plantationId || ''
    };

    setState(prev => ({ ...prev, users: [...prev.users, user] }));
    setNewUser({ username: '', password: '', role: UserRole.EMPLOYEE });
    alert("Compte créé ! N'oubliez pas de générer un nouveau lien pour mettre à jour les téléphones.");
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="flex justify-between items-end">
          <div>
            <h2 className="text-2xl font-black text-slate-800 dark:text-white">Équipe de Terrain</h2>
            <p className="text-slate-500 text-sm">Gérez vos employés et leurs accès.</p>
          </div>
          <button onClick={generateEmployeeLink} className="bg-amber-100 text-amber-700 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest border border-amber-200">Générer Lien Invité</button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1">
          <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm">
            <h3 className="text-lg font-black mb-6 dark:text-white">Nouvel Accès</h3>
            <form onSubmit={handleAddUser} className="space-y-4">
              <input required value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} placeholder="Utilisateur" className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border rounded-2xl outline-none dark:text-white font-bold" />
              <input required type="password" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} placeholder="Mot de passe" className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border rounded-2xl outline-none dark:text-white font-bold" />
              <select value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as UserRole})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border rounded-2xl outline-none dark:text-white font-bold">
                <option value={UserRole.EMPLOYEE}>Ouvrier (Accès Limité)</option>
                <option value={UserRole.ADMIN}>Gestionnaire (Accès Total)</option>
              </select>
              <button type="submit" className="w-full bg-green-700 text-white font-black py-4 rounded-2xl shadow-lg">Ajouter</button>
            </form>
          </div>
        </div>

        <div className="lg:col-span-2 bg-white dark:bg-slate-800 rounded-[2.5rem] shadow-sm border border-slate-100 dark:border-slate-700 overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-slate-50 dark:bg-slate-700/50">
              <tr>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Utilisateur</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Rôle</th>
                <th className="px-6 py-4 text-[10px] font-black text-slate-400 uppercase">Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-slate-700">
              {filteredUsers.map(u => (
                <tr key={u.id} className="hover:bg-slate-50/50 dark:hover:bg-slate-700/30 transition-colors">
                  <td className="px-6 py-4 text-sm font-bold dark:text-white">{u.username}</td>
                  <td className="px-6 py-4 text-[10px] font-black uppercase text-slate-400">{u.role}</td>
                  <td className="px-6 py-4">
                    {u.id !== state.currentUser?.id && <button onClick={() => setState(prev => ({ ...prev, users: prev.users.filter(usr => usr.id !== u.id) }))} className="text-red-500 font-bold text-xs uppercase">Retirer</button>}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

