            {filteredItems.map(item => (
              <a
                key={item.id}
                href={`#${item.id}`}
                onClick={(e) => {
                  e.preventDefault();
                  setActiveTab(item.id);
                  setIsOpen(false);
                }}
                className={`
                  w-full flex items-center space-x-4 px-4 py-3.5 rounded-2xl transition-all
                  ${activeTab === item.id 
                    ? 'bg-green-700 text-white shadow-lg shadow-green-900/20 scale-[1.02]' 
