            >
              <span className="text-2xl">🚪</span>
              <span>{t.logout}</span>
            </button>

            <div className="px-6 py-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Système</p>
