                <button type="submit" className={`flex-1 py-5 ${styles.btn} text-white font-black rounded-2xl shadow-xl transition-all uppercase text-[10px] tracking-widest`}>{t.save}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

