  expiryDate: string;
}

export interface User {
  id: string;
  username: string;
  role: UserRole;
  password?: string;
  plantationId: string;
  lastLoginAt?: string; // Pour détecter la première connexion
}

export type ActivityType = 
  | 'CREATION' 
  | 'MAINTENANCE' 
  | 'HARVEST' 
  | 'PRODUCTION' 
  | 'PACKAGING';

export interface Activity {
