  recipientId?: string; // Pour filtrer qui voit quoi
}

export interface AppState {
  plantations: Plantation[];
  users: User[];
  currentUser: User | null;
  activities: Activity[];
  sales: Sale[];
  cashMovements: CashMovement[];
