                disabled={username.trim().toLowerCase() === 'miguelf'}
                className="w-full px-6 py-4 bg-slate-50 dark:bg-slate-700 border border-slate-100 dark:border-slate-600 rounded-2xl outline-none dark:text-white focus:ring-4 focus:ring-green-500/10 focus:border-green-500 transition-all font-bold disabled:opacity-50 text-[16px]"
              />
            </div>

            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] ml-2">{t.username}</label>
              <input 
                type="text" value={username} onChange={e => setUsername(e.target.value)} required
