  { id: 'SYSTEM', name: 'Plameraie BST Master', ownerName: 'MiguelF', contactEmail: 'master@palmeraie.com', status: 'ACTIVE', expiryDate: '2099-01-01' },
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem('plameraie_db_v3');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.error("Erreur de lecture Storage", e);
    }
    return {
      plantations: INITIAL_PLANTATIONS,
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      notifications: [],
      language: 'FR',
      theme: 'light',
      isOnline: navigator.onLine,
      isSyncing: false
    };
  });

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [toasts, setToasts] = useState<{id: string, message: string, type: 'success' | 'error' | 'info'}[]>([]);

  const t = TRANSLATIONS[state.language];

  // Gestion du thème
  useEffect(() => {
    const root = window.document.documentElement;
    if (state.theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [state.theme]);

  // SAUVEGARDE LOCALE
  useEffect(() => {
    localStorage.setItem('plameraie_db_v3', JSON.stringify(state));
  }, [state]);

  // --- LOGIQUE D'ACTIVATION VIA LIEN (CONFIG URL) ---
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const configBase64 = urlParams.get('config');

    if (configBase64) {
      try {
        // Décoder la configuration base64 envoyée par le Super-Admin
        const decodedString = decodeURIComponent(escape(atob(configBase64)));
        const configData = JSON.parse(decodedString);

        if (configData.plantations && configData.users) {
          setState(prev => {
            // Fusionner les plantations (sans doublons)
            const updatedPlantations = [...prev.plantations];
            configData.plantations.forEach((p: Plantation) => {
              const index = updatedPlantations.findIndex(exist => exist.id === p.id);
              if (index > -1) updatedPlantations[index] = p;
              else updatedPlantations.push(p);
            });

            // Fusionner les utilisateurs (sans doublons)
            const updatedUsers = [...prev.users];
            configData.users.forEach((u: User) => {
              const index = updatedUsers.findIndex(exist => exist.id === u.id);
              if (index > -1) updatedUsers[index] = u;
              else updatedUsers.push(u);
            });

            return {
              ...prev,
              plantations: updatedPlantations,
              users: updatedUsers
            };
          });

          // Nettoyer l'URL et afficher un succès
          window.history.replaceState({}, document.title, window.location.pathname);
          addToast(state.language === 'FR' ? "Configuration chargée ! Connectez-vous." : "Config loaded! Please login.", 'success');
        }
      } catch (err) {
        console.error("Erreur lors de l'ingestion de la config:", err);
        addToast("Erreur de lien d'activation", 'error');
      }
