          onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))}
          onThemeToggle={() => {
            const nextTheme = state.theme === 'light' ? 'dark' : 'light';
            setState(p => ({ ...p, theme: nextTheme }));
