import { AppState, Plantation, User } from './types';

/**
 * syncService.ts - Version 3.0
 * Gère désormais la synchronisation globale des COMPTES (Users/Plantations) 
 * en plus des données opérationnelles.
 */

const CLOUD_STORAGE_KEY = 'plameraie_cloud_shared_v3';

interface CloudData {
    plantations: Plantation[];
    users: User[];
    activities: any[];
    sales: any[];
    cash: any[];
    deletedIds: string[];
}

const getCloudData = (): CloudData => {
    try {
        const cloud = localStorage.getItem(CLOUD_STORAGE_KEY);
        return cloud ? JSON.parse(cloud) : { plantations: [], users: [], activities: [], sales: [], cash: [], deletedIds: [] };
    } catch (e) {
        return { plantations: [], users: [], activities: [], sales: [], cash: [], deletedIds: [] };
    }
};

const saveToCloud = (data: CloudData) => {
    localStorage.setItem(CLOUD_STORAGE_KEY, JSON.stringify(data));
};

/**
 * Enregistre immédiatement de nouveaux comptes (utilisé lors de l'activation par lien)
 */
export const pushNewAccounts = (plantations: Plantation[], users: User[]) => {
    const cloud = getCloudData();
    plantations.forEach(p => {
        if (!cloud.plantations.find(cp => cp.id === p.id)) cloud.plantations.push(p);
    });
    users.forEach(u => {
        if (!cloud.users.find(cu => cu.id === u.id)) cloud.users.push(u);
    });
    saveToCloud(cloud);
};

export const syncDelete = (id: string) => {
    const cloud = getCloudData();
    if (!cloud.deletedIds.includes(id)) {
        cloud.deletedIds.push(id);
        cloud.activities = cloud.activities.filter(a => a.id !== id);
        cloud.sales = cloud.sales.filter(s => s.id !== id);
        cloud.cash = cloud.cash.filter(c => c.id !== id);
        // Supprimer aussi de la table plantations si c'est un ID de plantation
        cloud.plantations = cloud.plantations.filter(p => p.id !== id);
        saveToCloud(cloud);
    }
};

export const syncDataWithServer = async (state: AppState, setState: Function) => {
  const cloud = getCloudData();
  const plantationId = state.currentUser?.plantationId;
  const isMaster = state.currentUser?.role === 'SUPER_ADMIN';

  // 1. PUSH : Données opérationnelles locales -> Cloud
  let hasChanges = false;
  const unsyncedActivities = state.activities.filter(a => !a.synced);
  const unsyncedSales = state.sales.filter(s => !s.synced);

  unsyncedActivities.forEach(a => {
      if (!cloud.activities.find(ca => ca.id === a.id) && !cloud.deletedIds.includes(a.id)) {
          cloud.activities.push({ ...a, synced: true });
          hasChanges = true;
      }
  });

  unsyncedSales.forEach(s => {
      if (!cloud.sales.find(cs => cs.id === s.id) && !cloud.deletedIds.includes(s.id)) {
          cloud.sales.push({ ...s, synced: true });
          hasChanges = true;
      }
  });

  // PUSH : Mises à jour de statut de plantation (si Master)
  if (isMaster) {
      cloud.plantations = state.plantations;
      hasChanges = true;
  }

  if (hasChanges) saveToCloud(cloud);

  // 2. PULL : Cloud -> Local
  const merge = (local: any[], server: any[], filterById: boolean = true) => {
      const map = new Map();
      local.forEach(item => map.set(item.id, item));
      server.forEach(item => {
          if (!filterById || isMaster || item.plantationId === plantationId) {
              if (!cloud.deletedIds.includes(item.id)) {
                  map.set(item.id, { ...item, synced: true });
              }
          }
      });
      cloud.deletedIds.forEach(id => map.delete(id));
      return Array.from(map.values());
  };

  const finalActivities = merge(state.activities, cloud.activities);
  const finalSales = merge(state.sales, cloud.sales);
  const finalPlantations = merge(state.plantations, cloud.plantations, false);
  const finalUsers = merge(state.users, cloud.users, false);

  // Déterminer si un changement d'état est requis
  const needsUpdate = 
      finalActivities.length !== state.activities.length ||
      finalSales.length !== state.sales.length ||
      finalPlantations.length !== state.plantations.length ||
      finalUsers.length !== state.users.length ||
      // Vérifier les changements de statut internes aux objets (ex: status SUSPENDED)
      JSON.stringify(finalPlantations) !== JSON.stringify(state.plantations);

  if (needsUpdate) {
      setState((prev: AppState) => ({
          ...prev,
          activities: finalActivities.sort((a,b) => b.updatedAt - a.updatedAt),
          sales: finalSales.sort((a,b) => b.updatedAt - a.updatedAt),
          plantations: finalPlantations,
          users: finalUsers,
          isSyncing: false
      }));
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { User, UserRole, AppState, Activity, Sale, CashMovement, Notification, Plantation } from './types.ts';
import { TRANSLATIONS } from './constants.tsx';
import Dashboard from './components/Dashboard.tsx';
import Sidebar from './components/Sidebar.tsx';
import Header from './components/Header.tsx';
import Login from './components/Login.tsx';
import ActivityModule from './components/ActivityModule.tsx';
import SalesModule from './components/SalesModule.tsx';
import CashModule from './components/CashModule.tsx';
import StatsModule from './components/StatsModule.tsx';
import UserManagement from './components/UserManagement.tsx';
import ChatBot from './components/ChatBot.tsx';
import TutorialModule from './components/TutorialModule.tsx';
import ProductionModule from './components/ProductionModule.tsx';
import SuperAdminModule from './components/SuperAdminModule.tsx';
import Toast from './components/Toast.tsx';
import { syncDataWithServer, syncDelete, pushNewAccounts } from './syncService.ts';

const INITIAL_USERS: User[] = [
  { id: 'master-01', username: 'MiguelF', role: UserRole.SUPER_ADMIN, password: 'MF-05', plantationId: 'SYSTEM' },
];

const INITIAL_PLANTATIONS: Plantation[] = [
  { id: 'SYSTEM', name: 'Plameraie BST Master', ownerName: 'MiguelF', contactEmail: 'master@palmeraie.com', status: 'ACTIVE', expiryDate: '2099-01-01' },
];

const App: React.FC = () => {
  const [state, setState] = useState<AppState>(() => {
    try {
      const saved = localStorage.getItem('plameraie_db_v3');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.error("Erreur de lecture Storage", e);
    }
    return {
      plantations: INITIAL_PLANTATIONS,
      users: INITIAL_USERS,
      currentUser: null,
      activities: [],
      sales: [],
      cashMovements: [],
      notifications: [],
      language: 'FR',
      theme: 'light',
      isOnline: navigator.onLine,
      isSyncing: false
    };
  });

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [toasts, setToasts] = useState<{id: string, message: string, type: 'success' | 'error' | 'info'}[]>([]);
  const [inspectedPlantationId, setInspectedPlantationId] = useState<string | null>(null);

  const t = TRANSLATIONS[state.language];

  useEffect(() => {
    const root = window.document.documentElement;
    if (state.theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');
  }, [state.theme]);

  useEffect(() => {
    localStorage.setItem('plameraie_db_v3', JSON.stringify(state));
  }, [state]);

  // Sync boucle principale
  useEffect(() => {
    // On sync même si pas de currentUser pour récupérer les nouveaux comptes créés par MiguelF
    const syncInterval = setInterval(() => {
      syncDataWithServer(state, setState);
    }, 3000);
    return () => clearInterval(syncInterval);
  }, [state.currentUser?.id, state.plantations.length]);

  // Traitement du lien d'activation (Config)
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const configBase64 = urlParams.get('config');
    if (configBase64) {
      try {
        const decodedString = decodeURIComponent(escape(atob(configBase64)));
        const configData = JSON.parse(decodedString);
        if (configData.plantations && configData.users) {
          // IMPORTANT: Pousser immédiatement vers le Cloud pour que la connexion fonctionne
          pushNewAccounts(configData.plantations, configData.users);

          setState(prev => {
            const updatedPlantations = [...prev.plantations];
            configData.plantations.forEach((p: Plantation) => {
                if (!updatedPlantations.find(exist => exist.id === p.id)) updatedPlantations.push(p);
            });
            const updatedUsers = [...prev.users];
            configData.users.forEach((u: User) => {
                if (!updatedUsers.find(exist => exist.id === u.id)) updatedUsers.push(u);
            });
            return { ...prev, plantations: updatedPlantations, users: updatedUsers };
          });
          window.history.replaceState({}, document.title, window.location.pathname);
          addToast("Configuration chargée ! Vous pouvez vous connecter.", 'success');
        }
      } catch (err) {
        addToast("Erreur lors de l'activation du lien.", 'error');
      }
    }
  }, []);

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 3500);
  };

  const handleLogin = (user: User) => {
    const updatedUsers = state.users.map(u => 
      u.id === user.id ? { ...u, lastLoginAt: new Date().toISOString() } : u
    );
    setState(prev => ({ ...prev, currentUser: user, users: updatedUsers }));
    addToast(`Content de vous revoir !`, 'success');
    setActiveTab(user.role === UserRole.SUPER_ADMIN ? 'superadmin' : 'dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setInspectedPlantationId(null);
    addToast("Déconnexion", 'info');
  };

  const effectivePlantationId = useMemo(() => {
    if (state.currentUser?.role === UserRole.SUPER_ADMIN) return inspectedPlantationId || 'SYSTEM';
    return state.currentUser?.plantationId || 'SYSTEM';
  }, [state.currentUser, inspectedPlantationId]);

  const currentPlantation = useMemo(() => 
    state.plantations.find(p => p.id === effectivePlantationId),
  [state.plantations, effectivePlantationId]);

  const addActivity = (activity: any) => {
    const newActivity = { 
        ...activity, 
        id: `act-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`, 
        plantationId: state.currentUser!.plantationId, 
        updatedAt: Date.now(), 
        synced: false 
    };
    setState(prev => ({ ...prev, activities: [newActivity, ...prev.activities] }));
    addToast("Activité sauvegardée !");
  };

  const deleteActivity = (id: string) => {
    if (window.confirm("Supprimer cette opération ?")) {
        syncDelete(id);
        setState(prev => ({ ...prev, activities: prev.activities.filter(a => a.id !== id) }));
        addToast("Supprimé avec succès", 'info');
    }
  };

  const addSale = (sale: any) => {
    const newSale = { 
        ...sale, 
        id: `sale-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`, 
        plantationId: state.currentUser!.plantationId, 
        updatedAt: Date.now(), 
        synced: false 
    };
    setState(prev => ({ ...prev, sales: [newSale, ...prev.sales] }));
    addToast("Vente enregistrée !", 'success');
  };

  const deleteSale = (id: string) => {
    if (window.confirm("Supprimer cette vente ?")) {
        syncDelete(id);
        setState(prev => ({ ...prev, sales: prev.sales.filter(s => s.id !== id) }));
        addToast("Vente retirée", 'info');
    }
  };

  const renderContent = () => {
    // Si compte suspendu (sauf pour MiguelF)
    if (state.currentUser?.role !== UserRole.SUPER_ADMIN && currentPlantation?.status === 'SUSPENDED') {
        return (
            <div className="flex flex-col items-center justify-center min-h-[60vh] text-center p-10 bg-white dark:bg-slate-800 rounded-[3rem] shadow-xl">
                <div className="text-7xl mb-6">🚫</div>
                <h2 className="text-3xl font-black text-slate-800 dark:text-white tracking-tighter">Accès Suspendu</h2>
                <p className="text-slate-500 mt-4 max-w-sm">Votre accès a été temporairement désactivé par l'administrateur système.</p>
                <button onClick={handleLogout} className="mt-8 px-10 py-4 bg-slate-900 text-white rounded-2xl font-black uppercase text-xs tracking-widest">Retour</button>
            </div>
        );
    }

    if (state.currentUser?.role === UserRole.SUPER_ADMIN && !inspectedPlantationId) {
        return <SuperAdminModule state={state} setState={setState} t={t} onInspect={(id) => { setInspectedPlantationId(id); setActiveTab('dashboard'); }} />;
    }

    const scopedState = { ...state, 
        activities: state.activities.filter(a => a.plantationId === effectivePlantationId), 
        sales: state.sales.filter(s => s.plantationId === effectivePlantationId), 
        cashMovements: state.cashMovements.filter(c => c.plantationId === effectivePlantationId) 
    };

    switch (activeTab) {
      case 'dashboard': return <Dashboard state={scopedState} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={scopedState} onAdd={addActivity} onDelete={deleteActivity} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={scopedState} onAdd={addActivity} onDelete={deleteActivity} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={scopedState} onAdd={addActivity} onDelete={deleteActivity} t={t} />;
      case 'production': return <ProductionModule state={scopedState} onAdd={addActivity} onDelete={deleteActivity} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={scopedState} onAdd={addActivity} onDelete={deleteActivity} t={t} />;
      case 'sales': return <SalesModule state={scopedState} onAdd={addSale} onDelete={deleteSale} t={t} />;
      case 'cash': return <CashModule state={scopedState} t={t} />;
      case 'stats': return <StatsModule state={scopedState} t={t} />;
      case 'users': return <UserManagement state={state} setState={setState} t={t} />;
      case 'tutorial': return <TutorialModule t={t} />;
      case 'superadmin': return <SuperAdminModule state={state} setState={setState} t={t} onInspect={(id) => setInspectedPlantationId(id)} />;
      default: return <Dashboard state={scopedState} t={t} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      {!state.currentUser ? (
        <Login onLogin={handleLogin} users={state.users} t={t} theme={state.theme} language={state.language} onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))} onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))} addToast={addToast} />
      ) : (
        <>
          <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} userRole={state.currentUser.role} t={t} onLogout={handleLogout} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
          <div className="flex-1 flex flex-col min-w-0">
            <Header t={t} theme={state.theme} language={state.language} onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))} onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))} searchQuery={searchQuery} setSearchQuery={setSearchQuery} user={state.currentUser} notifications={state.notifications} markAllRead={() => {}} onHelpClick={() => setActiveTab('tutorial')} onMenuToggle={() => setIsSidebarOpen(true)} currentPlantation={currentPlantation} />
            {inspectedPlantationId && (
                <div className="bg-amber-600 text-white px-8 py-2 flex justify-between items-center shadow-lg">
                    <p className="text-[10px] font-black uppercase tracking-widest">👁️ Mode Surveillance : {currentPlantation?.name}</p>
                    <button onClick={() => { setInspectedPlantationId(null); setActiveTab('superadmin'); }} className="bg-white/20 px-4 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest">Quitter</button>
                </div>
            )}
            <main className="flex-1 overflow-y-auto p-4 md:p-10 custom-scrollbar">{renderContent()}</main>
          </div>
          <ChatBot state={state} t={t} />
        </>
      )}
      <div className="fixed bottom-4 left-4 z-[500] flex flex-col space-y-2 pointer-events-none">
        {toasts.map(toast => <Toast key={toast.id} message={toast.message} type={toast.type} onClose={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} />)}
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState, Plantation, User, UserRole } from '../types';
import { syncDelete } from '../syncService';

interface SuperAdminModuleProps {
  state: AppState;
  setState: React.Dispatch<React.SetStateAction<AppState>>;
  t: any;
  onInspect: (plantationId: string) => void;
}

const SuperAdminModule: React.FC<SuperAdminModuleProps> = ({ state, setState, t, onInspect }) => {
  const [newPlantation, setNewPlantation] = useState({ 
    name: '', owner: '', email: '', adminUsername: 'admin', adminPassword: '' 
  });
  const [showCode, setShowCode] = useState<string | null>(null);

  const generateActivationLink = (pId: string) => {
    const p = state.plantations.find(pl => pl.id === pId);
    const companyUsers = state.users.filter(u => u.plantationId === pId);
    const config = { plantations: [p], users: companyUsers };
    const base64 = btoa(unescape(encodeURIComponent(JSON.stringify(config))));
    return `${window.location.origin}${window.location.pathname}?config=${base64}`;
  };

  const shareWhatsApp = (pId: string) => {
    const p = state.plantations.find(pl => pl.id === pId);
    const adminUser = state.users.find(u => u.plantationId === pId && u.role === UserRole.ADMIN);
    const link = generateActivationLink(pId);

    const message = `*PLAMERAIE BST - Accès Officiel*\n\n` +
      `Bonjour ${p?.ownerName},\n` +
      `Voici vos accès pour la plantation *${p?.name}*.\n\n` +
      `*Code:* ${pId}\n` +
      `*Identifiant:* ${adminUser?.username}\n` +
      `*Mot de passe:* ${adminUser?.password}\n\n` +
      `👉 *CLIQUEZ ICI POUR ACTIVER:* ${link}`;

    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const addPlantation = (e: React.FormEvent) => {
    e.preventDefault();
    const id = `PALM-${Math.floor(100 + Math.random() * 899)}`;

    const plantation: Plantation = {
      id, 
      name: newPlantation.name, 
      ownerName: newPlantation.owner, 
      contactEmail: newPlantation.email,
      status: 'ACTIVE', 
      expiryDate: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
    };

    const adminUser: User = { 
      id: `user-${Date.now()}`, 
      username: newPlantation.adminUsername, 
      password: newPlantation.adminPassword || '1234', 
      role: UserRole.ADMIN, 
      plantationId: id 
    };

    setState(prev => ({ 
      ...prev, 
      plantations: [...prev.plantations, plantation], 
      users: [...prev.users, adminUser] 
    }));

    setShowCode(id);
    setNewPlantation({ name: '', owner: '', email: '', adminUsername: 'admin', adminPassword: '' });
  };

  const toggleStatus = (pId: string) => {
    setState(prev => ({
        ...prev,
        plantations: prev.plantations.map(p => 
            p.id === pId ? { ...p, status: p.status === 'ACTIVE' ? 'SUSPENDED' : 'ACTIVE' } : p
        )
    }));
  };

  const deletePlantation = (pId: string) => {
    if (window.confirm("❗ ATTENTION : Cette action supprimera définitivement cette palmeraie et tous ses utilisateurs. Confirmer ?")) {
        syncDelete(pId);
        setState(prev => ({
            ...prev,
            plantations: prev.plantations.filter(p => p.id !== pId),
            users: prev.users.filter(u => u.plantationId !== pId),
            activities: prev.activities.filter(a => a.plantationId !== pId),
            sales: prev.sales.filter(s => s.plantationId !== pId)
        }));
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">
      <div className="bg-gradient-to-br from-slate-900 via-slate-800 to-green-900 text-white p-10 rounded-[3rem] shadow-2xl relative overflow-hidden border border-slate-700">
        <div className="relative z-10">
          <h2 className="text-4xl font-black mb-1 tracking-tighter">👑 MiguelF Control</h2>
          <p className="text-slate-400 font-bold uppercase text-[10px] tracking-[0.3em]">Master Console Plameraie BST</p>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-green-500/10 rounded-full blur-3xl -mr-32 -mt-32"></div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-700">
          <h3 className="text-xl font-black mb-6 dark:text-white flex items-center">
            <span className="mr-2">➕</span> Inscrire un Client
          </h3>
          <form onSubmit={addPlantation} className="space-y-5">
            <div className="space-y-4 pb-4 border-b border-slate-100 dark:border-slate-700">
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Nom Palmeraie</label>
                <input required placeholder="Ex: Avocatier Sud" value={newPlantation.name} onChange={e => setNewPlantation({...newPlantation, name: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border-none rounded-2xl outline-none dark:text-white font-bold" />
              </div>
              <div>
                <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Gérant</label>
                <input required placeholder="M. Kouamé" value={newPlantation.owner} onChange={e => setNewPlantation({...newPlantation, owner: e.target.value})} className="w-full px-5 py-4 bg-slate-50 dark:bg-slate-700 border-none rounded-2xl outline-none dark:text-white font-bold" />
              </div>
