        const parsed = JSON.parse(saved);
        // On s'assure que les données démo sont bien présentes même en cas de mise à jour
        if (!parsed.activities.some((a: any) => a.plantationId === 'DEMO-BST')) {
          parsed.activities = [...parsed.activities, ...DEMO_ACTIVITIES];
          parsed.sales = [...parsed.sales, ...DEMO_SALES];
          parsed.cashMovements = [...parsed.cashMovements, ...DEMO_CASH];
        }
        return parsed;
      }
    } catch (e) {}
    return {
      plantations: INITIAL_PLANTATIONS,
      users: INITIAL_USERS,
      currentUser: null,
      activities: DEMO_ACTIVITIES,
      sales: DEMO_SALES,
      cashMovements: DEMO_CASH,
      notifications: [],
      language: 'FR',
      theme: 'light',
      isOnline: navigator.onLine,
      isSyncing: false
    };
  });

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [toasts, setToasts] = useState<{id: string, message: string, type: 'success' | 'error' | 'info'}[]>([]);
  const [inspectedPlantationId, setInspectedPlantationId] = useState<string | null>(null);

  const t = TRANSLATIONS[state.language];

  // EFFET POUR LE THÈME SOMBRE/CLAIR (Indispensable)
  useEffect(() => {
    const root = window.document.documentElement;
    if (state.theme === 'dark') {
      root.classList.add('dark');
    } else {
      root.classList.remove('dark');
    }
  }, [state.theme]);

  useEffect(() => {
    localStorage.setItem('plameraie_db_final_v1', JSON.stringify(state));
  }, [state]);

  const effectivePlantationId = useMemo(() => {
    if (state.currentUser?.role === UserRole.SUPER_ADMIN) return inspectedPlantationId || 'SYSTEM';
    return state.currentUser?.plantationId || 'SYSTEM';
  }, [state.currentUser, inspectedPlantationId]);

  const currentPlantation = useMemo(() => 
    state.plantations.find(p => p.id === effectivePlantationId),
  [state.plantations, effectivePlantationId]);

  const scopedState = useMemo(() => ({
    ...state,
    activities: state.activities.filter(a => a.plantationId === effectivePlantationId),
    sales: state.sales.filter(s => s.plantationId === effectivePlantationId),
    cashMovements: state.cashMovements.filter(c => c.plantationId === effectivePlantationId)
  }), [state, effectivePlantationId]);

  const handleLogin = (user: User) => {
    const updatedUsers = state.users.map(u => u.id === user.id ? { ...u, lastLoginAt: new Date().toISOString() } : u);
    setState(prev => ({ ...prev, currentUser: user, users: updatedUsers }));
    setActiveTab(user.role === UserRole.SUPER_ADMIN ? 'superadmin' : 'dashboard');
  };

  const handleLogout = () => {
    setState(prev => ({ ...prev, currentUser: null }));
    setInspectedPlantationId(null);
  };

  const addToast = (message: string, type: 'success' | 'error' | 'info' = 'success') => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const renderContent = () => {
    if (state.currentUser?.role === UserRole.SUPER_ADMIN && !inspectedPlantationId && activeTab !== 'superadmin' && activeTab !== 'tutorial') {
        return (
          <div className="space-y-8">
            <SuperAdminModule state={state} setState={setState} t={t} onInspect={(id) => { setInspectedPlantationId(id); setActiveTab('dashboard'); }} />
            {scopedState.activities.length === 0 && (
              <div className="bg-amber-50 dark:bg-amber-900/20 p-8 rounded-[2rem] border-2 border-dashed border-amber-200 dark:border-amber-800 text-center">
                 <p className="text-amber-800 dark:text-amber-400 font-black uppercase text-xs tracking-widest mb-4">Vous êtes sur le compte maître MiguelF (Vide)</p>
                 <button 
                  onClick={() => { setInspectedPlantationId('DEMO-BST'); setActiveTab('dashboard'); }}
                  className="bg-amber-600 text-white px-8 py-4 rounded-2xl font-black uppercase text-xs tracking-widest hover:bg-amber-700 transition-all shadow-xl"
                 >
                   👁️ Voir les données de démonstration
                 </button>
              </div>
            )}
          </div>
        );
    }

    switch (activeTab) {
      case 'dashboard': return <Dashboard state={scopedState} t={t} />;
      case 'creation': return <ActivityModule type="CREATION" state={scopedState} onAdd={(a) => setState(p => ({...p, activities: [{...a, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.activities]}))} t={t} />;
      case 'maintenance': return <ActivityModule type="MAINTENANCE" state={scopedState} onAdd={(a) => setState(p => ({...p, activities: [{...a, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.activities]}))} t={t} />;
      case 'harvest': return <ActivityModule type="HARVEST" state={scopedState} onAdd={(a) => setState(p => ({...p, activities: [{...a, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.activities]}))} t={t} />;
      case 'production': return <ProductionModule state={scopedState} onAdd={(a) => setState(p => ({...p, activities: [{...a, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.activities]}))} t={t} />;
      case 'packaging': return <ActivityModule type="PACKAGING" state={scopedState} onAdd={(a) => setState(p => ({...p, activities: [{...a, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.activities]}))} t={t} />;
      case 'sales': return <SalesModule state={scopedState} onAdd={(s) => setState(p => ({...p, sales: [{...s, id: Date.now().toString(), plantationId: effectivePlantationId, updatedAt: Date.now()}, ...p.sales]}))} t={t} />;
      case 'cash': return <CashModule state={scopedState} t={t} />;
      case 'stats': return <StatsModule state={scopedState} t={t} />;
      case 'users': return <UserManagement state={state} setState={setState} t={t} />;
      case 'tutorial': return <TutorialModule t={t} />;
      case 'superadmin': return <SuperAdminModule state={state} setState={setState} t={t} onInspect={(id) => setInspectedPlantationId(id)} />;
      default: return <Dashboard state={scopedState} t={t} />;
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 dark:bg-slate-900 transition-colors">
      {!state.currentUser ? (
        <Login onLogin={handleLogin} users={state.users} t={t} theme={state.theme} language={state.language} onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))} onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))} addToast={addToast} />
      ) : (
        <>
          <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} userRole={state.currentUser.role} t={t} onLogout={handleLogout} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
          <div className="flex-1 flex flex-col min-w-0">
            <Header t={t} theme={state.theme} language={state.language} onThemeToggle={() => setState(p => ({ ...p, theme: p.theme === 'light' ? 'dark' : 'light' }))} onLanguageToggle={() => setState(p => ({ ...p, language: p.language === 'FR' ? 'EN' : 'FR' }))} searchQuery={searchQuery} setSearchQuery={setSearchQuery} user={state.currentUser} notifications={state.notifications} markAllRead={() => {}} onHelpClick={() => setActiveTab('tutorial')} onMenuToggle={() => setIsSidebarOpen(true)} currentPlantation={currentPlantation} />
            {inspectedPlantationId && (
                <div className="bg-amber-600 text-white px-8 py-2 flex justify-between items-center shadow-lg border-b border-amber-500">
                    <p className="text-[10px] font-black uppercase tracking-widest flex items-center"><span className="mr-2 text-lg">👁️</span> Surveillance de {currentPlantation?.name}</p>
                    <button onClick={() => { setInspectedPlantationId(null); setActiveTab('superadmin'); }} className="bg-white/20 px-4 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-white/30">Quitter</button>
                </div>
            )}
            <main className="flex-1 overflow-y-auto p-4 md:p-10 custom-scrollbar">{renderContent()}</main>
          </div>
          <ChatBot state={state} t={t} />
        </>
      )}
      <div className="fixed bottom-4 left-4 z-[500] flex flex-col space-y-2 pointer-events-none">
        {toasts.map(toast => <Toast key={toast.id} message={toast.message} type={toast.type} onClose={() => setToasts(prev => prev.filter(t => t.id !== toast.id))} />)}
      </div>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { AppState } from '../types';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';

interface DashboardProps {
  state: AppState;
  t: any;
}

const Dashboard: React.FC<DashboardProps> = ({ state, t }) => {
  const totalSales = useMemo(() => state.sales.reduce((acc, s) => acc + s.total, 0), [state.sales]);
  const totalCosts = useMemo(() => state.activities.reduce((acc, a) => acc + a.cost, 0), [state.activities]);
  const netBalance = totalSales - totalCosts;

  // AGRÉGATION CHRONOLOGIQUE PAR JOUR
  const chartData = useMemo(() => {
    if (!state.sales || state.sales.length === 0) return [];

    // Regrouper par date
    const grouped = state.sales.reduce((acc, sale) => {
      acc[sale.date] = (acc[sale.date] || 0) + sale.total;
      return acc;
    }, {} as Record<string, number>);

    // Convertir en tableau trié
    return Object.entries(grouped)
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([date, amount]) => ({
        name: date.split('-').reverse().slice(0, 2).join('/'),
        amount
      }));
  }, [state.sales]);

  const stats = [
    { label: t.totalSales, value: `${totalSales.toLocaleString()} FCFA`, color: 'text-green-600', icon: '💰', bg: 'bg-green-50 dark:bg-green-900/10' },
    { label: t.totalCosts, value: `${totalCosts.toLocaleString()} FCFA`, color: 'text-red-600', icon: '📉', bg: 'bg-red-50 dark:bg-red-900/10' },
    { label: t.netBalance, value: `${netBalance.toLocaleString()} FCFA`, color: netBalance >= 0 ? 'text-amber-600' : 'text-red-600', icon: '🏦', bg: 'bg-amber-50 dark:bg-amber-900/10' },
    { label: t.totalActivities, value: state.activities.length, color: 'text-blue-600', icon: '🗓️', bg: 'bg-blue-50 dark:bg-blue-900/10' }
  ];

  return (
    <div className="space-y-10 animate-in fade-in slide-in-from-bottom-5 duration-700">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-4xl font-black text-slate-800 dark:text-white tracking-tighter">{t.dashboard}</h2>
          <p className="text-slate-500 dark:text-slate-400 font-medium">Suivi en temps réel de votre exploitation.</p>
        </div>
        <div className="flex items-center space-x-3 bg-white dark:bg-slate-800 px-4 py-2 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-700">
           <span className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></span>
           <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Système Intelligent Prêt</span>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className={`p-8 rounded-[2rem] shadow-sm border border-slate-100 dark:border-slate-700 ${stat.bg} group transition-all hover:scale-[1.03] hover:shadow-xl`}>
            <div className="flex justify-between items-start">
              <div>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</p>
                <h3 className={`text-2xl font-black ${stat.color}`}>{stat.value}</h3>
              </div>
              <span className="text-3xl bg-white dark:bg-slate-700 w-12 h-12 rounded-2xl flex items-center justify-center shadow-sm group-hover:rotate-12 transition-transform">
                {stat.icon}
              </span>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm min-h-[450px] flex flex-col">
          <div className="flex items-center justify-between mb-8">
            <div>
              <h3 className="text-xl font-black text-slate-800 dark:text-white">Évolution des Ventes</h3>
              <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Performance Commerciale Globale</p>
            </div>
            <div className="bg-green-50 dark:bg-green-900/20 text-green-600 px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest">
              Flux Financier
            </div>
          </div>
          <div className="flex-1 w-full min-h-[300px]">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="colorSales" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#16a34a" stopOpacity={0.2}/>
                      <stop offset="95%" stopColor="#16a34a" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} fontSize={10} stroke="#94a3b8" dy={10} />
                  <YAxis axisLine={false} tickLine={false} fontSize={10} stroke="#94a3b8" />
                  <Tooltip 
                    contentStyle={{ borderRadius: '24px', border: 'none', boxShadow: '0 20px 25px -5px rgb(0 0 0 / 0.1)', fontWeight: 'bold' }}
                  />
                  <Area type="monotone" dataKey="amount" name="Ventes (FCFA)" stroke="#16a34a" strokeWidth={4} fillOpacity={1} fill="url(#colorSales)" animationDuration={1500} />
                </AreaChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50 space-y-4">
                 <span className="text-6xl">📊</span>
                 <p className="font-black uppercase text-xs tracking-[0.2em]">Aucune donnée de vente à afficher</p>
              </div>
            )}
          </div>
        </div>

        <div className="bg-white dark:bg-slate-800 p-8 rounded-[2.5rem] border border-slate-100 dark:border-slate-700 shadow-sm flex flex-col">
          <h3 className="text-xl font-black text-slate-800 dark:text-white mb-6">Journal des Travaux</h3>
          <div className="space-y-4 flex-1 overflow-y-auto custom-scrollbar pr-2">
            {state.activities.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-slate-400 opacity-50">
                <span className="text-4xl mb-2">📭</span>
                <p className="text-xs font-black uppercase">Aucune activité</p>
              </div>
            ) : (
              state.activities.slice(0, 8).map(activity => (
                <div key={activity.id} className="flex items-center space-x-4 p-4 rounded-2xl bg-slate-50 dark:bg-slate-700/30 hover:bg-slate-100 transition-all group border border-transparent hover:border-slate-200">
                  <div className="w-10 h-10 rounded-xl bg-white dark:bg-slate-800 shadow-sm flex items-center justify-center text-xl group-hover:scale-110 transition-transform">
                    {activity.type === 'CREATION' ? '🌱' : activity.type === 'HARVEST' ? '🚜' : activity.type === 'PRODUCTION' ? '🏭' : '⚙️'}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-black text-slate-800 dark:text-white truncate">{activity.label}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{activity.date}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs font-black text-slate-700 dark:text-slate-300">-{activity.cost.toLocaleString()}</p>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
